import { useEffect, useRef, useState } from "react";
import {
  DefaultGameInfoOverlay,
  DefaultSubscriberCelebration,
  DefaultSuperChatCelebration
} from "@repo/game-kit/react";
import { createRuntimeCommandClient, type RuntimeCommandClient } from "@repo/game-kit/browser";
import { engineDevAdapter, registerGameDev } from "@repo/game-dev/browser";
import { buildRejectedCommandResult } from "@repo/game-kit";

import { sampleGameName } from "./appMeta";
import {
  streamStage,
  type ConnectionStatus,
  type RuntimeWebSocketConstructor
} from "./gameState";
import { createSampleGameEngine, sampleGameDefinition, type SampleGameEngine } from "./game";
import "./styles.css";

type AppProps = {
  controlWsUrl?: string;
  WebSocketCtor?: RuntimeWebSocketConstructor;
  gameEngine?: SampleGameEngine;
};

const connectionLabels: Record<ConnectionStatus, string> = {
  "not-configured": "Not configured",
  connecting: "Connecting",
  connected: "Connected",
  disconnected: "Disconnected",
  error: "Error"
};

export function App({
  controlWsUrl,
  WebSocketCtor = globalThis.WebSocket as unknown as RuntimeWebSocketConstructor,
  gameEngine
}: AppProps) {
  const [ownedEngine, setOwnedEngine] = useState(createSampleGameEngine);
  const engine = gameEngine ?? ownedEngine;
  const [simulation, setSimulation] = useState(() => engine.getState());
  const [connectionStatus, setConnectionStatus] =
    useState<ConnectionStatus>("connecting");
  const transportRef = useRef<{ engine: SampleGameEngine; controlWsUrl: string | undefined; WebSocketCtor: RuntimeWebSocketConstructor; client: RuntimeCommandClient } | undefined>(undefined);

  useEffect(() => {
    // React refresh preserves renderer state. A changed simulation module gets a new engine/history.
    if (!gameEngine && ownedEngine.definition !== sampleGameDefinition) {
      ownedEngine.resume({ pending: "discard" });
      setOwnedEngine(createSampleGameEngine());
    }
  }, [gameEngine, ownedEngine, sampleGameDefinition]);

  useEffect(() => {
    setSimulation(engine.getState());
    return engine.subscribe(() => setSimulation(engine.getState()));
  }, [engine]);

  useEffect(() => {
    const previous = transportRef.current;
    const client = previous?.engine === engine && previous.controlWsUrl === controlWsUrl && previous.WebSocketCtor === WebSocketCtor
      ? previous.client : createRuntimeCommandClient({
      controlWsUrl, WebSocketCtor, onConnectionStatusChange: setConnectionStatus, loggerName: "sample-game",
      autoStart: false,
      applyCommand(command) {
        const receipt = engine.dispatch(command);
        if (receipt.status === "applied") return receipt.result;
        return { commandId: command.commandId, streamId: command.streamId, deploymentId: command.deploymentId,
          runtimeInstanceId: command.runtimeInstanceId, status: "accepted", runtimeState: "debugger-frozen" };
      }
    });
    transportRef.current = { engine, controlWsUrl, WebSocketCtor, client };
    const unsubscribe = engine.subscribePendingResults(completion => {
      client.reportResult(completion.status === "applied" && completion.result
        ? completion.result : buildRejectedCommandResult(completion.input, completion.error ?? "Queued input discarded"));
    });
    const cleanupDev = registerGameDev(engineDevAdapter(engine));
    client.start();
    return () => { cleanupDev(); unsubscribe(); client.stop(); };
  }, [engine, controlWsUrl, WebSocketCtor]);

  useEffect(() => {
    let animationFrame = 0;
    let previousFrameTime = performance.now();
    let accumulatedSeconds = 0;
    const fixedDelta = 1 / engine.getSnapshot().tickRate;

    const tick = (frameTime: number) => {
      const deltaSeconds = Math.max(0, Math.min((frameTime - previousFrameTime) / 1000, 0.25));
      previousFrameTime = frameTime;
      accumulatedSeconds += deltaSeconds * engine.getTimeScale();
      while (accumulatedSeconds >= fixedDelta) {
        engine.advance();
        accumulatedSeconds -= fixedDelta;
      }

      animationFrame = window.requestAnimationFrame(tick);
    };

    animationFrame = window.requestAnimationFrame(tick);

    return () => window.cancelAnimationFrame(animationFrame);
  }, [engine]);

  const gameState = simulation.runtime;
  const sprite = simulation.sprite;
  const activeCelebration = gameState.celebrationQueue[0];
  const runtimeStateLabel = gameState.paused ? "Paused" : "Running";
  const spriteStyle = {
    backgroundColor: gameState.config.squareColor,
    left: `${(sprite.x / streamStage.width) * 100}%`,
    top: `${(sprite.y / streamStage.height) * 100}%`,
    width: `${(streamStage.spriteSize / streamStage.width) * 100}%`
  };
  const overlayItems = [
    {
      label: "Runtime",
      value: connectionLabels[connectionStatus],
      testId: "connection-status"
    },
    {
      label: "State",
      value: runtimeStateLabel,
      testId: "run-state"
    },
    {
      label: "Latest command",
      value: gameState.latestCommandLabel,
      testId: "latest-command"
    },
    {
      label: "Latest chat",
      value: gameState.latestChatMessage,
      testId: "latest-chat-message"
    },
    {
      label: "Latest sub",
      value: gameState.latestSubscriberMessage,
      testId: "latest-subscriber-message"
    },
    {
      label: "Latest Super Chat",
      value: gameState.latestSuperChatMessage,
      testId: "latest-superchat-message"
    }
  ];

  return (
    <main className="game-shell" aria-label={sampleGameName}>
      <section className="arena" aria-label="Animated arena">
        <div className="arena-grid" />
        <div
          className="sprite"
          data-testid="animated-sprite"
          style={spriteStyle}
        />

        {activeCelebration?.kind === "subscriber" ? (
          <DefaultSubscriberCelebration
            key={activeCelebration.eventId}
            className="subscriber-celebration"
            celebration={activeCelebration}
            config={gameState.defaults.subscriberOverlay}
          />
        ) : null}

        {activeCelebration?.kind === "superchat" ? (
          <DefaultSuperChatCelebration
            key={activeCelebration.eventId}
            className="superchat-celebration"
            celebration={activeCelebration}
            config={gameState.defaults.superChatOverlay}
          />
        ) : null}

        {gameState.overlayVisible ? (
          <DefaultGameInfoOverlay
            className="runtime-overlay"
            config={gameState.defaults.gameInfoOverlay}
            items={overlayItems}
          />
        ) : null}
      </section>
    </main>
  );
}

