import { z } from "zod";
import { createInitialSharedGameState, parseRuntimeControlCommand } from "@repo/game-kit";
import { createGameEngine, createSharedGameStateSchema, defineGame } from "@repo/game-kit/engine";
import { parseSquareColor } from "./colorValidation";
import { sampleGameConfig, sampleGameOverlayDefaults } from "./gameConfig";
import { advanceSprite, applyGameCommand, initialSprite, streamStage } from "./gameState";

export const sampleConfigSchema = z.object({
  speed: z.number().finite().positive().max(3),
  squareColor: z.string().refine(value => parseSquareColor(value) !== undefined, "Unsupported square color")
}).strict();

export const sampleStateSchema = z.object({
  runtime: createSharedGameStateSchema(sampleConfigSchema),
  sprite: z.object({
    x: z.number().finite().min(0).max(streamStage.width - streamStage.spriteSize),
    y: z.number().finite().min(0).max(streamStage.height - streamStage.spriteSize),
    velocityX: z.number().finite(), velocityY: z.number().finite()
  }).strict(),
  celebrationRemainingMs: z.number().finite().nonnegative()
}).strict();

export const sampleGameDefinition = defineGame({
  id: "sample-game", schemaVersion: "1", simulationRevision: "sample-game-engine-2",
  stateSchema: sampleStateSchema, configSchema: sampleConfigSchema,
  inputSchema: z.unknown().transform(parseRuntimeControlCommand), initialConfig: { ...sampleGameConfig },
  inspector: {
    "sprite.x": { label: "Square X", group: "World", editable: true, min: 0, max: streamStage.width - streamStage.spriteSize, step: 1 },
    "sprite.y": { label: "Square Y", group: "World", editable: true, min: 0, max: streamStage.height - streamStage.spriteSize, step: 1 },
    "sprite.velocityX": { label: "Horizontal velocity", group: "World", editable: true, min: -2000, max: 2000 },
    "sprite.velocityY": { label: "Vertical velocity", group: "World", editable: true, min: -2000, max: 2000 },
    "celebrationRemainingMs": { label: "Celebration time remaining", group: "Presentation" }
  },
  createInitialState(config) {
    return { runtime: createInitialSharedGameState(config, sampleGameOverlayDefaults), sprite: { ...initialSprite }, celebrationRemainingMs: 0 };
  },
  applyCommand(state, command) {
    const previousCelebration = state.runtime.celebrationQueue[0]?.eventId;
    const previousDuration = state.runtime.defaults.celebrationDurationMs;
    const application = applyGameCommand(state.runtime, command);
    state.runtime = application.state;
    if (command.type === "resetGame" && application.result.status === "applied") state.sprite = { ...initialSprite };
    if (previousCelebration !== state.runtime.celebrationQueue[0]?.eventId || previousDuration !== state.runtime.defaults.celebrationDurationMs) {
      state.celebrationRemainingMs = state.runtime.celebrationQueue.length ? state.runtime.defaults.celebrationDurationMs : 0;
    }
    return { state, result: application.result };
  },
  step(state, context) {
    if (!state.runtime.paused) state.sprite = advanceSprite(state.sprite, context.deltaSeconds, state.runtime.config.speed);
    if (state.runtime.celebrationQueue.length) {
      state.celebrationRemainingMs = Math.max(0, state.celebrationRemainingMs - context.deltaMs);
      if (state.celebrationRemainingMs < 1e-7) {
        state.runtime.celebrationQueue = state.runtime.celebrationQueue.slice(1);
        state.celebrationRemainingMs = state.runtime.celebrationQueue.length ? state.runtime.defaults.celebrationDurationMs : 0;
      }
    }
    return { state };
  }
});

export const createSampleGameEngine = () => createGameEngine(sampleGameDefinition, { seed: "sample-game" });
export type SampleGameEngine = ReturnType<typeof createSampleGameEngine>;
export type SampleSimulationState = z.infer<typeof sampleStateSchema>;

