import type { GameCommandResult, NormalizedChatEvent } from "@repo/protocol";
import {
  applySharedGameCommand,
  buildRejectedCommandResult,
  createInitialSharedGameState,
  type Celebration,
  type ConnectionStatus,
  type RuntimeWebSocket,
  type RuntimeControlCommand,
  type RuntimeWebSocketConstructor,
  type SharedChatEventResult,
  type SharedGameState
} from "@repo/game-kit";

import { parseSquareColor } from "./colorValidation";
import { sampleGameConfig, sampleGameOverlayDefaults } from "./gameConfig";

export type GameConfig = {
  speed: number;
  squareColor: string;
};

export type GameState = SharedGameState<GameConfig>;

export type SpriteState = {
  x: number;
  y: number;
  velocityX: number;
  velocityY: number;
};

export const streamStage = {
  width: 1080,
  height: 1920,
  spriteSize: 96
} as const;

const arenaWidth = streamStage.width;
const arenaHeight = streamStage.height;
const spriteSize = streamStage.spriteSize;

export const initialSprite: SpriteState = {
  x: 120,
  y: 180,
  velocityX: 280,
  velocityY: 360
};

export function createInitialGameState(): GameState {
  return createInitialSharedGameState(
    { ...sampleGameConfig },
    sampleGameOverlayDefaults
  );
}

export function advanceSprite(
  sprite: SpriteState,
  deltaSeconds: number,
  speed: number
): SpriteState {
  const nextSprite = {
    ...sprite,
    x: sprite.x + sprite.velocityX * deltaSeconds * speed,
    y: sprite.y + sprite.velocityY * deltaSeconds * speed
  };

  if (nextSprite.x <= 0 || nextSprite.x >= arenaWidth - spriteSize) {
    nextSprite.velocityX *= -1;
    nextSprite.x = Math.max(0, Math.min(nextSprite.x, arenaWidth - spriteSize));
  }

  if (nextSprite.y <= 0 || nextSprite.y >= arenaHeight - spriteSize) {
    nextSprite.velocityY *= -1;
    nextSprite.y = Math.max(0, Math.min(nextSprite.y, arenaHeight - spriteSize));
  }

  return nextSprite;
}

export function applyGameCommand(
  state: GameState,
  command: RuntimeControlCommand
): { state: GameState; result: GameCommandResult } {
  return applySharedGameCommand(state, command, {
    initialConfig: { ...sampleGameConfig },
    initialDefaults: sampleGameOverlayDefaults,
    mergeGameConfig: mergeConfig,
    onChatEvent: applySampleChatEvent
  });
}

function applySampleChatEvent(
  state: GameState,
  chatEvent: NormalizedChatEvent
): SharedChatEventResult<GameConfig> {
  const squareColor =
    chatEvent.message.type === "text"
      ? parseSquareColor(chatEvent.message.text)
      : undefined;

  return {
    state: {
      ...state,
      config: squareColor
        ? {
            ...state.config,
            squareColor
          }
        : state.config
    },
    commands: squareColor ? ["setColor"] : []
  };
}

function mergeConfig(config: GameConfig, payload: Record<string, unknown>) {
  const squareColor =
    typeof payload.squareColor === "string"
      ? parseSquareColor(payload.squareColor)
      : undefined;

  return {
    speed:
      typeof payload.speed === "number" && payload.speed > 0
        ? Math.min(payload.speed, 3)
        : config.speed,
    squareColor: squareColor ?? config.squareColor
  };
}

export type {
  Celebration,
  ConnectionStatus,
  RuntimeWebSocket,
  RuntimeWebSocketConstructor
};
export { buildRejectedCommandResult };

