:root {
  color: #f7fbff;
  background: #101418;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

.game-shell {
  align-items: center;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.08), transparent 38%),
    #101418;
  display: grid;
  min-height: 100vh;
  overflow: hidden;
  padding: 0;
  place-items: center;
  position: relative;
}

.arena {
  aspect-ratio: 9 / 16;
  background:
    linear-gradient(135deg, rgba(54, 211, 153, 0.18), transparent 34%),
    linear-gradient(180deg, #1e2b32 0%, #172126 100%);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.18);
  height: min(100vh, calc(100vw * 1.777777778));
  overflow: hidden;
  position: relative;
  width: min(100vw, calc(100vh * 0.5625));
}

.arena-grid {
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.08) 1px, transparent 1px);
  background-size: 48px 48px;
  inset: 0;
  opacity: 0.5;
  position: absolute;
}

.sprite {
  aspect-ratio: 1;
  border: 3px solid rgba(255, 255, 255, 0.86);
  box-shadow:
    0 0 22px rgba(54, 211, 153, 0.42),
    inset 0 0 18px rgba(255, 255, 255, 0.22);
  left: 0;
  position: absolute;
  top: 0;
  transition: background-color 160ms ease;
  will-change: left, top;
}

.subscriber-celebration,
.superchat-celebration {
  align-items: center;
  animation: subscriber-pop 250ms ease-out;
  display: flex;
  gap: 18px;
  max-width: calc(100% - 56px);
  min-height: 104px;
  padding: 18px 22px;
  position: absolute;
  width: min(680px, calc(100% - 56px));
  z-index: 3;
}

.subscriber-celebration {
  box-shadow:
    0 18px 60px color-mix(in srgb, var(--accent-color) 34%, transparent),
    0 0 0 8px color-mix(in srgb, var(--accent-color) 12%, transparent);
}

.superchat-celebration {
  box-shadow:
    0 18px 60px color-mix(in srgb, var(--accent-color) 30%, transparent),
    0 0 0 8px color-mix(in srgb, var(--accent-color) 14%, transparent);
}

.subscriber-celebration img,
.subscriber-avatar-fallback {
  border-radius: 999px;
  flex: 0 0 auto;
  height: 72px;
  width: 72px;
}

.subscriber-celebration img {
  object-fit: cover;
}

.subscriber-avatar-fallback {
  align-items: center;
  background: var(--accent-color);
  color: var(--overlay-text-color);
  display: inline-flex;
  font-size: 36px;
  font-weight: 900;
  justify-content: center;
}

.subscriber-celebration div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.subscriber-celebration span,
.superchat-celebration span {
  color: var(--accent-color);
  font-size: 16px;
  font-weight: 900;
  text-transform: uppercase;
}

.subscriber-celebration strong,
.superchat-celebration strong {
  color: inherit;
  font-size: 42px;
  line-height: 1.04;
  min-width: 0;
  overflow-wrap: anywhere;
}

.superchat-amount {
  align-items: center;
  background: var(--accent-color);
  color: var(--overlay-text-color);
  display: inline-flex;
  flex: 0 0 auto;
  font-size: 30px;
  font-weight: 950;
  justify-content: center;
  min-height: 72px;
  min-width: 128px;
  padding: 10px 16px;
}

.superchat-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.superchat-copy p {
  color: inherit;
  font-size: 22px;
  font-weight: 800;
  line-height: 1.18;
  margin: 2px 0 0;
  max-height: 3.6em;
  overflow: hidden;
  overflow-wrap: anywhere;
}

.runtime-overlay {
  background: rgba(11, 18, 24, 0.86);
  border: 1px solid rgba(255, 255, 255, 0.16);
  display: grid;
  gap: 10px;
  left: 24px;
  max-width: calc(100% - 48px);
  padding: 14px;
  position: absolute;
  top: 24px;
  width: min(420px, calc(100% - 48px));
}

.runtime-overlay div {
  align-items: center;
  display: grid;
  gap: 12px;
  grid-template-columns: 116px minmax(0, 1fr);
}

.runtime-overlay span {
  color: var(--accent-color);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}

.runtime-overlay strong {
  color: inherit;
  font-size: 14px;
  font-weight: 700;
  min-width: 0;
  overflow-wrap: anywhere;
}

@keyframes subscriber-pop {
  0% {
    opacity: 0;
    transform: translateY(-28px) scale(0.92);
  }

  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 640px) {
  .game-shell {
    align-items: center;
  }

  .runtime-overlay {
    left: 14px;
    max-width: calc(100% - 28px);
    padding: 12px;
    top: 14px;
    width: calc(100% - 28px);
  }

  .runtime-overlay div {
    grid-template-columns: 1fr;
    gap: 4px;
  }

  .subscriber-celebration,
  .superchat-celebration {
    gap: 12px;
    min-height: 88px;
    padding: 14px;
  }

  .subscriber-celebration img,
  .subscriber-avatar-fallback {
    height: 56px;
    width: 56px;
  }

  .subscriber-celebration strong {
    font-size: 28px;
  }

  .superchat-celebration {
    align-items: stretch;
    flex-direction: column;
  }

  .superchat-amount {
    font-size: 24px;
    min-height: 0;
    min-width: 0;
    width: 100%;
  }

  .superchat-celebration strong {
    font-size: 28px;
  }

  .superchat-copy p {
    font-size: 18px;
  }
}

