import { createHash } from "node:crypto";
import { readFile, realpath } from "node:fs/promises";
import path from "node:path";
import { parseDocument } from "yaml";

export const NPM_GAME_SDK_MANIFEST_PATH = ".gamego/sdk.json";
export const NPM_GAME_SDK_VERSION = "0.4.0";
export const NPM_GAME_CONTRACT_VERSION = "1.0.0";
export const NPM_GAME_SDK_PACKAGES = ["@bubbleportal/devtools", "@bubbleportal/protocol", "@bubbleportal/sdk"] as const;
export type NpmGameSdkPackageName = typeof NPM_GAME_SDK_PACKAGES[number];
export type NpmGameSdkPackage = { version: string; integrity: string };
export type NpmGameSdkManifest = {
  schemaVersion: 1;
  distribution?: "npm";
  sdkVersion: string;
  gameContractVersion: string;
  packages: Record<NpmGameSdkPackageName, NpmGameSdkPackage>;
  sdkIdentity: string;
};

/** Hash npm tarball identities, not installation paths or unpacked timestamps. */
export function npmSdkIdentityForPackages(packages: Record<string, NpmGameSdkPackage>): string {
  const canonical = Object.fromEntries(Object.keys(packages).sort().map(name => {
    const entry = packages[name]!;
    return [name, { version: entry.version, integrity: entry.integrity }];
  }));
  return `sha256:${createHash("sha256").update(JSON.stringify(canonical)).digest("hex")}`;
}

export function validateNpmGameSdkManifest(value: unknown): NpmGameSdkManifest {
  const manifest = record(value);
  if (!manifest || manifest.schemaVersion !== 1 || (manifest.distribution !== undefined && manifest.distribution !== "npm")) fail("Unsupported npm SDK manifest version or distribution");
  if (manifest.sdkVersion !== NPM_GAME_SDK_VERSION || manifest.gameContractVersion !== NPM_GAME_CONTRACT_VERSION) fail("Unsupported npm SDK or game contract version");
  const packages = record(manifest.packages);
  if (!packages || Object.keys(packages).sort().join("\n") !== [...NPM_GAME_SDK_PACKAGES].sort().join("\n")) fail("npm SDK manifest must contain exactly the three public packages");
  for (const name of NPM_GAME_SDK_PACKAGES) {
    const entry = record(packages[name]);
    if (!entry || Object.keys(entry).sort().join(",") !== "integrity,version" || entry.version !== manifest.sdkVersion) fail(`npm SDK package ${name} must match sdkVersion ${manifest.sdkVersion}`);
    if (typeof entry.integrity !== "string" || !/^sha512-[A-Za-z0-9+/]{86}==$/.test(entry.integrity) || Buffer.from(entry.integrity.slice(7), "base64").toString("base64") !== entry.integrity.slice(7)) fail(`npm SDK package ${name} requires a canonical sha512 tarball integrity`);
  }
  const typed = manifest as NpmGameSdkManifest;
  if (typed.sdkIdentity !== npmSdkIdentityForPackages(typed.packages)) fail("npm SDK content identity does not match its manifest");
  return typed;
}

/** A renamed source bundle is still a source distribution, never an npm release. */
export function isBundledPublicGameSdk(input: { packageJson: unknown; bundledManifest: unknown; lockfileText: string }): boolean {
  const manifest = record(input.bundledManifest);
  if (manifest?.schemaVersion !== 3 || !Array.isArray(manifest.submodules) || manifest.submodules.length !== 1) return false;
  const entry = record(manifest.submodules[0]);
  if (!entry || entry.distribution !== "bundled" || entry.gameContractVersion !== NPM_GAME_CONTRACT_VERSION || typeof entry.path !== "string" || !entry.path.length || entry.path.includes("\\") || path.posix.isAbsolute(entry.path) || path.posix.normalize(entry.path).split("/").some(part => part === "..") || entry.path.includes(":")) return false;
  if (!Array.isArray(entry.packages) || [...entry.packages].sort().join(",") !== "game-dev,game-kit,game-protocol,protocol" || typeof entry.sdkIdentity !== "string" || !/^sha256:[a-f0-9]{64}$/.test(entry.sdkIdentity) || typeof entry.sdkVersion !== "string") return false;
  const packageJson = record(input.packageJson);
  const dependencies = record(packageJson?.dependencies) ?? {};
  const devDependencies = record(packageJson?.devDependencies) ?? {};
  const development = record(record(packageJson?.gameInstance)?.development);
  if (development?.sdkIdentity !== entry.sdkIdentity || development.sdkVersion !== entry.sdkVersion || dependencies["@bubbleportal/sdk"] !== "workspace:*" || devDependencies["@bubbleportal/devtools"] !== "workspace:*" || devDependencies["@bubbleportal/sdk"] !== undefined || dependencies["@bubbleportal/devtools"] !== undefined || devDependencies["@bubbleportal/protocol"] !== undefined || NPM_GAME_SDK_PACKAGES.some(name => record(packageJson?.optionalDependencies)?.[name] !== undefined)) return false;
  if (dependencies["@bubbleportal/protocol"] !== undefined && dependencies["@bubbleportal/protocol"] !== "workspace:*") return false;
  try {
    const document = parseDocument(input.lockfileText, { uniqueKeys: true });
    if (document.errors.length) return false;
    const lock = record(document.toJS({ maxAliasCount: 0 }));
    const importer = record(record(lock?.importers)?.["."]);
    if (!importer) return false;
    const targets = [{ name: "@bubbleportal/sdk", section: "dependencies", folder: "game-kit" }, { name: "@bubbleportal/devtools", section: "devDependencies", folder: "game-dev" }, ...(dependencies["@bubbleportal/protocol"] !== undefined ? [{ name: "@bubbleportal/protocol", section: "dependencies", folder: "game-protocol" }] : [])];
    return targets.every(({ name, section, folder }) => {
      const resolved = record(record(importer[section])?.[name]);
      return resolved?.specifier === "workspace:*" && resolved.version === `link:${path.posix.join(entry.path as string, "packages", folder)}`;
    });
  } catch { return false; }
}

export function hasPublicGameSdkDeclarations(packageJson: unknown): boolean {
  const value = record(packageJson);
  return NPM_GAME_SDK_PACKAGES.some(name => record(value?.dependencies)?.[name] !== undefined || record(value?.devDependencies)?.[name] !== undefined || record(value?.optionalDependencies)?.[name] !== undefined);
}

/** Validate the committed root importer and its actual resolved package graph. */
export function validateNpmGameSdkIdentity(input: { manifest: unknown; packageJson: unknown; lockfileText: string }): NpmGameSdkManifest {
  const manifest = validateNpmGameSdkManifest(input.manifest);
  const packageJson = record(input.packageJson);
  const metadata = record(packageJson?.gameInstance);
  const development = record(metadata?.development);
  if (metadata?.gameContractVersion !== manifest.gameContractVersion || development?.sdkIdentity !== manifest.sdkIdentity || development.sdkVersion !== manifest.sdkVersion) fail("package.json gameInstance development SDK identity/version must match the npm manifest");
  const dependencies = record(packageJson?.dependencies) ?? {};
  const devDependencies = record(packageJson?.devDependencies) ?? {};
  const optionalDependencies = record(packageJson?.optionalDependencies) ?? {};
  const required = { "@bubbleportal/sdk": dependencies["@bubbleportal/sdk"], "@bubbleportal/devtools": devDependencies["@bubbleportal/devtools"] };
  for (const [name, specifier] of Object.entries(required)) if (!exactSpecifier(specifier, manifest.sdkVersion)) fail(`package.json must pin ${name} to ${manifest.sdkVersion} (or an integrity-checked local tarball)`);
  if (dependencies["@bubbleportal/devtools"] !== undefined || devDependencies["@bubbleportal/sdk"] !== undefined || NPM_GAME_SDK_PACKAGES.some(name => optionalDependencies[name] !== undefined) || devDependencies["@bubbleportal/protocol"] !== undefined) fail("npm SDK and protocol belong in dependencies; devtools belongs only in devDependencies");
  if (dependencies["@bubbleportal/protocol"] !== undefined && !exactSpecifier(dependencies["@bubbleportal/protocol"], manifest.sdkVersion)) fail("package.json must pin its direct protocol dependency to sdkVersion");
  if (typeof input.lockfileText !== "string" || input.lockfileText.length > 4 * 1024 * 1024) fail("npm SDK requires a bounded pnpm lockfile");
  const document = parseDocument(input.lockfileText, { uniqueKeys: true });
  if (document.errors.length) fail(`Invalid pnpm lockfile: ${document.errors[0]!.message}`);
  const lock = record(document.toJS({ maxAliasCount: 0 }));
  if (!lock || Number(lock.lockfileVersion) !== 9) fail("npm SDK requires pnpm lockfile version 9");
  const importer = record(record(lock.importers)?.["."]);
  const packages = record(lock.packages);
  const snapshots = record(lock.snapshots);
  if (!importer || !packages || !snapshots) fail("npm SDK pnpm lockfile is missing its root importer, packages or snapshots");
  for (const name of Object.keys(record(lock.patchedDependencies) ?? {})) if (NPM_GAME_SDK_PACKAGES.some(publicName => name === publicName || name.startsWith(`${publicName}@`))) fail("npm SDK tarballs must not be patched");

  const resolved = new Map<NpmGameSdkPackageName, string>();
  const resolve = (name: NpmGameSdkPackageName, reference: unknown): Record<string, unknown> => {
    if (typeof reference !== "string") fail(`pnpm lockfile is missing the resolved ${name} package`);
    const baseReference = reference.split("(")[0]!;
    if (!exactSpecifier(baseReference, manifest.sdkVersion)) fail(`pnpm lockfile resolves an unsupported ${name} version or source`);
    const packageKey = `${name}@${baseReference}`;
    const packageEntry = record(packages[packageKey]);
    const snapshot = record(snapshots[`${name}@${reference}`]);
    const resolution = record(packageEntry?.resolution);
    if (!packageEntry || !snapshot || !resolution || resolution.integrity !== manifest.packages[name].integrity || resolution.type !== undefined) fail(`pnpm lockfile ${name} tarball integrity does not match the npm manifest`);
    if (isLocalTarball(baseReference) && (packageEntry.version !== manifest.sdkVersion || resolution.tarball !== baseReference)) fail(`pnpm lockfile local ${name} tarball metadata does not match sdkVersion`);
    if (packageEntry.version !== undefined && packageEntry.version !== manifest.sdkVersion) fail(`pnpm lockfile ${name} package version does not match sdkVersion`);
    if (resolution.tarball !== undefined && (typeof resolution.tarball !== "string" || !(isLocalTarball(resolution.tarball) || resolution.tarball.startsWith("https://")))) fail(`pnpm lockfile ${name} uses an unsupported tarball source`);
    const previous = resolved.get(name);
    if (previous !== undefined && previous !== packageKey) fail(`pnpm lockfile resolves multiple npm SDK identities for ${name}`);
    resolved.set(name, packageKey);
    return snapshot;
  };
  const rootResolve = (name: NpmGameSdkPackageName, section: "dependencies" | "devDependencies", specifier: unknown) => {
    const entry = record(record(importer[section])?.[name]);
    if (!entry || entry.specifier !== specifier) fail(`pnpm lockfile root ${name} specifier differs from package.json`);
    for (const other of ["dependencies", "devDependencies", "optionalDependencies"]) if (other !== section && record(importer[other])?.[name] !== undefined) fail(`pnpm lockfile puts ${name} in the wrong dependency section`);
    return resolve(name, entry.version);
  };
  const sdk = rootResolve("@bubbleportal/sdk", "dependencies", required["@bubbleportal/sdk"]);
  const devtools = rootResolve("@bubbleportal/devtools", "devDependencies", required["@bubbleportal/devtools"]);
  if (dependencies["@bubbleportal/protocol"] !== undefined) rootResolve("@bubbleportal/protocol", "dependencies", dependencies["@bubbleportal/protocol"]);
  else if (["dependencies", "devDependencies", "optionalDependencies"].some(section => record(importer[section])?.["@bubbleportal/protocol"] !== undefined)) fail("pnpm lockfile declares a protocol dependency absent from package.json");
  resolve("@bubbleportal/protocol", record(sdk.dependencies)?.["@bubbleportal/protocol"]);
  for (const snapshot of [sdk, devtools]) {
    for (const name of NPM_GAME_SDK_PACKAGES) {
      const reference = record(snapshot.dependencies)?.[name];
      if (reference !== undefined) resolve(name, reference);
      if (record(snapshot.optionalDependencies)?.[name] !== undefined) fail("npm SDK public packages must not be optional dependencies");
    }
  }
  return manifest;
}

/** Installation must finish before the default installed-package checks run. */
export async function readNpmGameSdkIdentity(root: string, options: { verifyInstalled?: boolean } = {}): Promise<string | undefined> {
  let text: string;
  try { text = await readFile(path.join(root, NPM_GAME_SDK_MANIFEST_PATH), "utf8"); }
  catch (error) {
    if (!notFound(error)) throw error;
    let packageText: string;
    try { packageText = await readFile(path.join(root, "package.json"), "utf8"); }
    catch (packageError) { if (notFound(packageError)) return undefined; throw packageError; }
    const packageJson = record(JSON.parse(packageText));
    if (hasPublicGameSdkDeclarations(packageJson)) {
      try {
        const [bundledText, lockfileText] = await Promise.all([readFile(path.join(root, ".streamforge-submodules.json"), "utf8"), readFile(path.join(root, "pnpm-lock.yaml"), "utf8")]);
        if (isBundledPublicGameSdk({ packageJson, bundledManifest: JSON.parse(bundledText), lockfileText })) return undefined;
      } catch (bundleError) { if (!notFound(bundleError)) throw bundleError; }
      fail(`npm SDK requires ${NPM_GAME_SDK_MANIFEST_PATH}`);
    }
    return undefined;
  }
  const [packageText, lockfileText] = await Promise.all([readFile(path.join(root, "package.json"), "utf8"), readFile(path.join(root, "pnpm-lock.yaml"), "utf8")]);
  const manifest = validateNpmGameSdkIdentity({ manifest: JSON.parse(text), packageJson: JSON.parse(packageText), lockfileText });
  if (options.verifyInstalled !== false) {
    const sdk = await installedPackage(root, "@bubbleportal/sdk", manifest);
    const devtools = await installedPackage(root, "@bubbleportal/devtools", manifest);
    const sdkProtocol = await installedPackage(path.dirname(sdk.file), "@bubbleportal/protocol", manifest);
    if (record(sdk.json.dependencies)?.["@bubbleportal/protocol"] !== manifest.sdkVersion) fail("Installed SDK must pin its protocol dependency to sdkVersion");
    if (record(devtools.json.dependencies)?.["@bubbleportal/protocol"] !== undefined) await installedPackage(path.dirname(devtools.file), "@bubbleportal/protocol", manifest);
    const packageJson = record(JSON.parse(packageText));
    if (record(packageJson?.dependencies)?.["@bubbleportal/protocol"] !== undefined) await installedPackage(root, "@bubbleportal/protocol", manifest);
    if (sdkProtocol.json.version !== manifest.sdkVersion) fail("Installed npm protocol version does not match the manifest");
  }
  return manifest.sdkIdentity;
}

async function installedPackage(from: string, name: NpmGameSdkPackageName, manifest: NpmGameSdkManifest) {
  let current = await realpath(from);
  for (;;) {
    const file = path.join(current, "node_modules", name, "package.json");
    let text: string;
    try { text = await readFile(file, "utf8"); }
    catch (error) {
      if (!notFound(error)) throw error;
      const parent = path.dirname(current);
      if (parent === current) fail(`Installed npm SDK package ${name} is missing`);
      current = parent;
      continue;
    }
    const json = record(JSON.parse(text));
    if (!json || json.name !== name || json.version !== manifest.packages[name].version) fail(`Installed npm SDK package ${name} version/name does not match the manifest`);
    return { file: await realpath(file), json };
  }
}

function record(value: unknown): Record<string, unknown> | undefined { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : undefined; }
function isLocalTarball(value: string) { return /^file:.+\.(?:tgz|tar\.gz)$/.test(value); }
function exactSpecifier(value: unknown, version: string): value is string { return typeof value === "string" && (value === version || isLocalTarball(value)); }
function notFound(error: unknown) { return error instanceof Error && "code" in error && error.code === "ENOENT"; }
function fail(message: string): never { throw new Error(message); }

