import { spawn } from "node:child_process";
import { chmod, mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { buildRuntimeChildEnv } from "./process-env.js";

import type { ChildProcess } from "node:child_process";
import type { LogForwarder } from "./log-forwarder.js";
import type { ProcessLauncher } from "./xvfb.js";

export const runtimeAudioDirectory = "/tmp/stream-runtime-audio";
export const runtimeAudioSource = "game.monitor";
export const runtimeAudioEnvironment = Object.freeze(audioEnvironment(runtimeAudioDirectory));

/** A private software sound device for this container; no host sound card is required. */
export class AudioController {
  status: "not_started" | "starting" | "ready" | "failed" | "stopped" = "not_started";
  readonly environment: Record<string, string>;
  private readonly directory: string;
  private process: ChildProcess | undefined;
  private exited = false;
  private stopping = false;
  private ownsDirectory = false;
  private ready = false;
  private startup: Promise<void> | undefined;
  private cleanup: Promise<void> | undefined;
  private cancellation: AbortController | undefined;
  private readonly probes = new Set<ChildProcess>();

  constructor(private readonly options: {
    logs: LogForwarder;
    launcher?: ProcessLauncher;
    /** Allows lifecycle tests to use an isolated temporary directory. */
    directory?: string;
    startupTimeoutMs?: number;
    probeTimeoutMs?: number;
    shutdownTimeoutMs?: number;
  }) {
    this.directory = options.directory ?? runtimeAudioDirectory;
    this.environment = audioEnvironment(this.directory);
  }

  async start() {
    if (this.startup) return this.startup;
    if (this.ready) return;
    this.stopping = false;
    this.status = "starting";
    this.cancellation = new AbortController();
    this.startup = this.startAudio(this.cancellation);
    try { await this.startup; }
    finally { this.startup = undefined; }
  }

  async stop() {
    this.stopping = true;
    this.cancellation?.abort(new Error("Audio startup cancelled"));
    await this.startup?.catch(() => undefined);
    await this.cleanupAudio();
    this.status = "stopped";
  }

  private async startAudio(cancellation: AbortController) {
    let deadline: ReturnType<typeof setTimeout> | undefined;
    const signal = cancellation.signal;
    try {
      // Refuse existing paths, including symlinks. Only a directory we create is cleaned up.
      await mkdir(this.directory, { mode: 0o700 });
      this.ownsDirectory = true;
      await chmod(this.directory, 0o700);
      await writeFile(path.join(this.directory, "alsa.conf"), alsaConfiguration(this.environment.PULSE_SERVER!),
        { mode: 0o600, flag: "wx" });
      const script = path.join(this.directory, "default.pa");
      await writeFile(script, [
        ".fail",
        "load-module module-null-sink sink_name=game rate=44100 channels=2",
        `load-module module-native-protocol-unix socket=${path.join(this.directory, "native")} auth-anonymous=1`,
        "set-default-sink game",
        `set-default-source ${runtimeAudioSource}`,
        ""
      ].join("\n"), { mode: 0o600, flag: "wx" });
      signal.throwIfAborted();
      deadline = setTimeout(() => cancellation.abort(new Error("Audio startup timed out")),
        this.options.startupTimeoutMs ?? 10_000);
      this.exited = false;
      this.process = (this.options.launcher ?? spawn)("pulseaudio", [
        "--daemonize=no", "--system=no", "--use-pid-file=no", "--exit-idle-time=-1",
        "--disallow-exit=yes", "--disable-shm=yes", "--realtime=no", "--high-priority=no",
        "--log-target=stderr", "--log-level=notice", "-n", "--file", script
      ], { stdio: "pipe", env: buildRuntimeChildEnv({ ...this.environment,
        PULSE_RUNTIME_PATH: this.directory, PULSE_STATE_PATH: path.join(this.directory, "state") }) });
      this.attachProcess(this.process, cancellation);
      while (!signal.aborted) {
        const result = await this.probeSources(signal);
        signal.throwIfAborted();
        if (result.code === 0 && result.output.split(/\r?\n/).some(line => line.trim().split(/\s+/)[1] === runtimeAudioSource)) {
          this.ready = true;
          this.status = "ready";
          this.options.logs.emit("runtime", "info", `game audio capture ready source=${runtimeAudioSource}`);
          return;
        }
        await pause(100, signal);
      }
      signal.throwIfAborted();
    } catch (error) {
      this.status = "failed";
      try { await this.cleanupAudio(); }
      catch (cleanupError) { throw new AggregateError([error, cleanupError], "Audio startup and cleanup failed"); }
      throw error;
    } finally { clearTimeout(deadline); }
  }

  private attachProcess(child: ChildProcess, cancellation: AbortController) {
    child.once("error", error => {
      if (!child.pid) this.exited = true;
      this.ready = false;
      this.status = "failed";
      const failure = new Error(`PulseAudio process failed: ${error.message}`);
      this.options.logs.emit("runtime", "error", failure.message);
      cancellation.abort(failure);
    });
    child.once("exit", (code, signal) => {
      this.exited = true;
      this.ready = false;
      if (!this.stopping) {
        this.status = "failed";
        const failure = new Error(`PulseAudio exited code=${code} signal=${signal}`);
        this.options.logs.emit("runtime", "error", failure.message);
        cancellation.abort(failure);
      }
    });
    child.stderr?.on("data", (chunk: Buffer | string) => {
      const message = String(chunk).trim().slice(0, 2048);
      if (message) this.options.logs.emit("runtime", "warn", `PulseAudio: ${message}`);
    });
  }

  private probeSources(signal: AbortSignal): Promise<{ code: number | null; output: string }> {
    signal.throwIfAborted();
    const child = (this.options.launcher ?? spawn)("pactl", [
      `--server=${this.environment.PULSE_SERVER}`, "list", "short", "sources"
    ], { stdio: "pipe", env: buildRuntimeChildEnv({ ...this.environment, LC_ALL: "C" }) });
    this.probes.add(child);
    return new Promise((resolve, reject) => {
      let output = "";
      let settled = false;
      const finish = (error?: Error, code: number | null = null) => {
        if (settled) return;
        settled = true;
        clearTimeout(timeout);
        signal.removeEventListener("abort", cancelled);
        if (error) {
          try { child.kill("SIGKILL"); } catch { /* Cleanup makes a bounded termination attempt. */ }
          reject(error);
        }
        else resolve({ code, output });
      };
      const cancelled = () => finish(signal.reason instanceof Error ? signal.reason : new Error("Audio startup cancelled"));
      const timeout = setTimeout(() => finish(new Error("Audio readiness probe timed out")),
        this.options.probeTimeoutMs ?? 1_000);
      child.stdout?.on("data", (chunk: Buffer | string) => {
        output += String(chunk);
        if (output.length > 65_536) finish(new Error("Audio readiness probe output exceeded its limit"));
      });
      child.once("error", error => {
        if (!child.pid) this.probes.delete(child);
        finish(new Error(`Audio readiness probe failed: ${error.message}`));
      });
      child.once("close", code => { this.probes.delete(child); finish(undefined, code); });
      signal.addEventListener("abort", cancelled, { once: true });
      if (signal.aborted) cancelled();
    });
  }

  private async cleanupAudio() {
    if (this.cleanup) return this.cleanup;
    this.cleanup = this.performCleanup();
    try { await this.cleanup; }
    finally { this.cleanup = undefined; }
  }

  private async performCleanup() {
    this.stopping = true;
    this.ready = false;
    for (const probe of this.probes) await terminate(probe, this.options.shutdownTimeoutMs ?? 1_000);
    this.probes.clear();
    if (this.process && !this.exited) await terminate(this.process, this.options.shutdownTimeoutMs ?? 1_000);
    this.process = undefined;
    // Keep the directory if termination failed, rather than unlinking a live daemon's socket.
    if (this.ownsDirectory) {
      await rm(this.directory, { recursive: true, force: true });
      this.ownsDirectory = false;
    }
  }
}

function audioEnvironment(directory: string): Record<string, string> {
  return {
    PULSE_SERVER: `unix:${directory}/native`, PULSE_SINK: "game", PULSE_SOURCE: runtimeAudioSource,
    ALSA_CONFIG_PATH: `${directory}/alsa.conf`
  };
}

function alsaConfiguration(server: string) {
  // The PCM Pulse plugin accepts server/device; the control plugin accepts server/sink.
  return `</usr/share/alsa/alsa.conf>\npcm.!default {\n  type pulse\n  server ${JSON.stringify(server)}\n  device "game"\n}\nctl.!default {\n  type pulse\n  server ${JSON.stringify(server)}\n  sink "game"\n}\n`;
}

async function terminate(child: ChildProcess, timeoutMs: number) {
  if (child.exitCode !== null || child.signalCode !== null) return;
  const exited = new Promise<void>(resolve => child.once("exit", () => resolve()));
  try { child.kill("SIGTERM"); } catch { /* Escalation still attempts termination. */ }
  if (await within(exited, timeoutMs)) return;
  try { child.kill("SIGKILL"); } catch { /* The bounded wait below reports a failure. */ }
  if (!await within(exited, timeoutMs)) throw new Error("Audio process did not stop after SIGKILL");
}

async function within(completion: Promise<void>, timeoutMs: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try { return await Promise.race([completion.then(() => true), new Promise<false>(resolve => { timer = setTimeout(() => resolve(false), timeoutMs); })]); }
  finally { clearTimeout(timer); }
}

function pause(delayMs: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    const cancelled = () => { clearTimeout(timer); signal.removeEventListener("abort", cancelled); reject(signal.reason); };
    const timer = setTimeout(() => { signal.removeEventListener("abort", cancelled); resolve(); }, delayMs);
    signal.addEventListener("abort", cancelled, { once: true });
    if (signal.aborted) cancelled();
  });
}

