      ...(values["runtime-image"] ? { runtimeImage: values["runtime-image"] } : {}),
      gameSource: values["archive-file"] ? { kind: "git_archive", archivePath: path.resolve(values["archive-file"]), commitSha: values["game-commit"]! }
        : values["game-dir"] ? { kind: "local_directory", directory: path.resolve(values["game-dir"]) } : values["archive-url"] ? { kind: "github_archive", archiveUrl: values["archive-url"], ...(values["game-commit"] ? { commitSha: values["game-commit"] } : {}) } : { kind: "sample" }
