import { readFile } from "node:fs/promises";
import path from "node:path";

export async function resolveConformanceConfig(directory: string, override?: Record<string, unknown>) {
  if (override !== undefined) {
    if (!isObject(override)) throw new Error("Config override must be a JSON object");
    return { payload: structuredClone(override), source: "override" as const };
  }
  const manifest: unknown = JSON.parse(await readFile(path.join(directory, "package.json"), "utf8"));
  const gameInstance = isObject(manifest) && isObject(manifest.gameInstance) ? manifest.gameInstance : undefined;
  if (!gameInstance || !("setConfigPayload" in gameInstance)) return { payload: {}, source: "empty-default" as const };
  if (!isObject(gameInstance.setConfigPayload)) throw new Error("package.json gameInstance.setConfigPayload must be a JSON object");
  return { payload: gameInstance.setConfigPayload, source: "package.json" as const };
}

function isObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

import type { GameCommand, GameCommandResult } from "@repo/protocol";

export type PendingConformanceResults = Map<string, (result: GameCommandResult) => void>;

/** A receipt can arrive before application; only a scoped terminal result completes the check. */
export function waitForAppliedCommand(
  command: GameCommand,
  pending: PendingConformanceResults,
  send: () => void,
  timeoutMs = 10_000
): Promise<GameCommandResult> {
  return new Promise((resolve, reject) => {
    let accepted = false;
    const finish = (result?: GameCommandResult, error?: Error) => {
      clearTimeout(timeout);
      pending.delete(command.commandId);
      if (error) reject(error); else resolve(result!);
    };
    // Repeated receipts do not extend the command's bounded application deadline.
    const timeout = setTimeout(() => finish(undefined, new Error(accepted
      ? `${command.type}: accepted, but no terminal acknowledgement within ${timeoutMs}ms`
      : `No acknowledgement for ${command.type} within ${timeoutMs}ms`)), timeoutMs);
    pending.set(command.commandId, result => {
      if (result.commandId !== command.commandId || result.streamId !== command.streamId ||
          result.deploymentId !== command.deploymentId || result.runtimeInstanceId !== command.runtimeInstanceId) {
        finish(undefined, new Error("Acknowledgement has incorrect command or session identity"));
      } else if (result.status === "accepted") {
        accepted = true;
      } else if (result.status === "applied") {
        finish(result);
      } else {
        finish(undefined, new Error(`${command.type}: ${result.status} (${result.error ?? "no details"})`));
      }
    });
    try { send(); } catch (error) { finish(undefined, error instanceof Error ? error : new Error(String(error))); }
  });
}

import { createHash, randomUUID } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createServer } from "node:net";
import path from "node:path";
import { WebSocketServer, type WebSocket } from "ws";
import { chatEventToGameCommand, subscriberEventToGameCommand, GameCommandResultSchema, GameCommandSchema, type GameCommand, type GameCommandResult, type RuntimeAgentLogEvent } from "@repo/protocol";
import { sdkIdentityForPackages } from "@repo/protocol/sdk-identity";
import { GameServerController, readGameSdkIdentity, supportedGameContractVersion, type TestableGameSource } from "./game-server.js";
import { LogForwarder } from "./log-forwarder.js";
import { RendererController } from "./renderer-controller.js";
import { RuntimeControlAgent } from "./runtime-control-agent.js";
import { XvfbController } from "./xvfb.js";
import { waitForAppliedCommand } from "./conformance-results.js";
import { resolveConformanceConfig } from "./conformance-config.js";

export type ConformanceOptions = {
  repoRoot: string;
  outputDirectory: string;
  gameSource: TestableGameSource;
  config?: Record<string, unknown>;
  runtimeImage?: string;
  gameCommit?: string;
  width?: number;
  height?: number;
  display?: string;
  preparationTimeoutMs?: number;
};

/** Runs the production preparation, control agent and renderer without an encoder or stream. */
export async function checkGameConformance(options: ConformanceOptions) {
  const output = path.resolve(options.outputDirectory);
  await mkdir(output, { recursive: true });
  const identity = { streamId: "conformance", deploymentId: randomUUID(), runtimeInstanceId: randomUUID() };
  const events: RuntimeAgentLogEvent[] = [];
  const logs = new LogForwarder(identity, event => { events.push(event); });
  const checks: Array<{ name: string; passed: boolean; detail?: string }> = [];
  const results: GameCommandResult[] = [];
  const pending = new Map<string, (result: GameCommandResult) => void>();
  const server = new WebSocketServer({ host: "127.0.0.1", port: 0 });
  await new Promise<void>((resolve, reject) => { server.once("listening", resolve); server.once("error", reject); });
  let runtime: WebSocket | undefined;
  server.on("connection", socket => {
    runtime = socket;
    socket.on("message", data => {
      let message: unknown;
      try { message = JSON.parse(String(data)); } catch { return; }
      if (!message || typeof message !== "object" || !("result" in message)) return;
      const parsed = GameCommandResultSchema.safeParse(message.result);
      if (parsed.success) { results.push(parsed.data); pending.get(parsed.data.commandId)?.(parsed.data); }
    });
  });
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("Conformance control server did not bind");
  const [gamePort, controlPort] = await Promise.all([freePort(), freePort()]);
  const agent = new RuntimeControlAgent({ identity, runtimeVersion: "conformance", orchestratorRuntimeWsUrl: `ws://127.0.0.1:${address.port}`, gameControlPort: controlPort, startedAt: new Date().toISOString(), logs });
  const display = options.display ?? ":98";
  const width = options.width ?? 1080;
  const height = options.height ?? 1920;
  const xvfb = process.platform === "linux" ? new XvfbController({ display, width, height, logs }) : undefined;
  let config: Record<string, unknown> = options.config ?? {};
  let configSource: string = "unavailable";
  let lockfileHash: string | undefined;
  const game = new GameServerController({
    port: gamePort, controlWebSocketUrl: agent.gameControlUrl, gameSource: options.gameSource, repoRoot: options.repoRoot, logs,
    ...(options.preparationTimeoutMs !== undefined ? { preparationTimeoutMs: options.preparationTimeoutMs } : {}),
    onSourcePrepared: async directory => {
      // Read the tested snapshot before lifecycle scripts can modify package.json.
      const selected = await resolveConformanceConfig(directory, options.config);
      config = selected.payload; configSource = selected.source;
      lockfileHash = hash(await readFile(path.join(options.gameSource.kind === "sample" ? options.repoRoot : directory, "pnpm-lock.yaml")));
      logs.emit("game", "info", `Conformance starting configuration: ${configSource}`);
    }
  });
  const renderer = new RendererController({ gameUrl: `http://127.0.0.1:${gamePort}`, display, width, height, logs });
  let diagnostics: unknown;
  let failure: string | undefined;
  let sdkIdentity: string | undefined;
  let runtimeSdkIdentity: string | undefined;
  try {
    runtimeSdkIdentity = sdkIdentityForPackages(options.repoRoot, ["protocol", "game-kit", "game-dev"]).identity;
    await agent.start();
    await xvfb?.start();
    await game.start();
    sdkIdentity = options.gameSource.kind === "sample" ? runtimeSdkIdentity : await readGameSdkIdentity(game.sourceDirectory!);
    await game.waitUntilHealthy();
    checks.push({ name: "production source preparation and health", passed: true });
    await renderer.start();
    diagnostics = await renderer.captureDiagnostics(path.join(output, "ready.png"));
    checks.push({ name: "Chromium readiness", passed: true });
    if ((diagnostics as { localInspectorVisible: boolean }).localInspectorVisible) throw new Error("Local testing overlay is present in production mode");
    checks.push({ name: "local inspector absent", passed: true });
    const command = (type: GameCommand["type"], payload: Record<string, unknown> = {}) => GameCommandSchema.parse({ commandId: randomUUID(), ...identity, type, payload, issuedAt: new Date().toISOString(), issuedBy: "conformance", requireAck: true });
    const send = (input: GameCommand) => waitForAppliedCommand(input, pending, () => {
      if (!runtime || runtime.readyState !== runtime.OPEN) throw new Error("Runtime control connection is unavailable");
      runtime.send(JSON.stringify({ type: "runtime.command", command: input }));
    });
    for (const type of ["setConfig", "pause", "resume", "resetGame"] as const) {
      await send(command(type, type === "setConfig" ? config : {}));
      checks.push({ name: `${type} round trip`, passed: true });
    }
    const pause = command("pause");
    const original = await send(pause);
    const duplicate = await send(pause);
    if (JSON.stringify(original) !== JSON.stringify(duplicate)) throw new Error("Duplicate command did not return the cached result");
    checks.push({ name: "duplicate acknowledgement", passed: true });
    await send(command("resume"));
