import { spawn } from "node:child_process";
import { StringDecoder } from "node:string_decoder";
import { runtimeAudioSource } from "./audio-controller.js";
import { buildRuntimeChildEnv } from "./process-env.js";

import type { ChildProcess, SpawnOptions } from "node:child_process";
import type { LogForwarder } from "./log-forwarder.js";
import type { ProcessLauncher } from "./xvfb.js";

export type EncoderStatus =
  | "not_started"
  | "starting"
  | "streaming"
  | "failed"
  | "stopped";

export type EncoderMetrics = {
  fps?: number;
  bitrateKbps?: number;
  currentBitrateKbps?: number;
  targetBitrateKbps?: number;
  droppedFrames?: number;
  speed?: number;
  sampledAt?: string;
};

export type VideoCodec = "h264" | "hevc" | "av1";
export type AudioCodec = "aac";

export type AdaptiveBitrateOptions = {
  enabled: boolean;
  minimumVideoBitrate: string;
  stepDownRatio: number;
  congestionSpeedThreshold: number;
  congestionSampleCount: number;
};

export class EncoderController {
  private process: ChildProcess | undefined;
  status: EncoderStatus = "not_started";
  metrics: EncoderMetrics = {};
  private currentVideoBitrate: string;
  private congestionSamples = 0;

  constructor(
    private readonly options: {
      rtmpUrl: string;
      display: string;
      width: number;
      height: number;
      fps: number;
      videoBitrate: string;
      videoCodec: VideoCodec;
      audioEnabled: boolean;
      audioCodec: AudioCodec;
      audioSource?: string;
      audioEnvironment?: Readonly<Record<string, string>>;
      adaptiveBitrate: AdaptiveBitrateOptions;
      launcher?: ProcessLauncher;
      logs: LogForwarder;
      now?: () => string;
    }
  ) {
    this.currentVideoBitrate = options.videoBitrate;
    this.metrics = bitrateMetrics(options.videoBitrate, options.videoBitrate);
  }

  async start() {
    this.status = "starting";
    this.startProcess();
  }

  async stop() {
    this.process?.kill("SIGTERM");
    this.process = undefined;
    this.status = "stopped";
  }

  private startProcess() {
    // Progress belongs to this FFmpeg process, not the previous encoder run.
    this.metrics = bitrateMetrics(this.options.videoBitrate, this.currentVideoBitrate);
    this.congestionSamples = 0;
    const launcher = this.options.launcher ?? spawn;
    const args = buildFfmpegArgs({
      ...this.options,
      videoBitrate: this.currentVideoBitrate
    });
    const spawnOptions: SpawnOptions = {
      env: buildRuntimeChildEnv({ DISPLAY: this.options.display, ...this.options.audioEnvironment }),
      stdio: "pipe"
    };
    const nextProcess = launcher("ffmpeg", args, spawnOptions);

    this.process = nextProcess;
    this.attachLogs(nextProcess);
    if (this.options.audioEnabled) {
      this.options.logs.emit(
        "encoder",
        "info",
        "game audio capture enabled with AAC for RTMP/RTMPS ingest"
      );
    }
    this.options.logs.emit(
      "encoder",
      "info",
      `ffmpeg encoder started codec=${this.options.videoCodec} bitrate=${this.currentVideoBitrate}`
    );
  }

  private attachLogs(processToAttach: ChildProcess) {
    const decoder = new StringDecoder("utf8");
    const maximumLineLength = 16_384;
    let pending = "";
    let discardUntilDelimiter = false;
    const processLine = (line: string) => {
      if (this.process !== processToAttach || !line) return;
      if (line.length > maximumLineLength) return;
      const metrics = parseFfmpegProgress(line);
      if (metrics) {
        this.metrics = {
          ...this.metrics,
          ...metrics,
          ...bitrateMetrics(this.options.videoBitrate, this.currentVideoBitrate),
          sampledAt: (this.options.now ?? (() => new Date().toISOString()))()
        };
        this.status = "streaming";
        this.maybeLowerBitrate(metrics);
      }
      if (/connection refused|failed to|unable to|no such file/i.test(line)) {
        this.status = "failed";
        this.options.logs.emit("encoder", "error", line);
        return;
      }
      // Progress is already represented by current heartbeat metrics. Persisting
      // every FFmpeg stats line creates two redundant history rows per second.
      // Match the whole stats line so an appended diagnostic is never hidden.
      if (/^\s*frame=\s*\d+(?:\s+(?:fps|q|L?size|time|bitrate|dup|drop|speed)=\s*\S+)*\s*$/.test(line)) return;
      this.options.logs.emit("encoder", "info", line);
    };
    const consume = (text: string, flush = false) => {
      const lines = (pending + text).split(/[\r\n]/);
      pending = lines.pop() ?? "";
      for (const line of lines) {
        if (this.process !== processToAttach) return;
        if (discardUntilDelimiter) { discardUntilDelimiter = false; continue; }
        processLine(line);
      }
      if (pending.length > maximumLineLength) { pending = ""; discardUntilDelimiter = true; }
      if (flush && !discardUntilDelimiter) { processLine(pending); pending = ""; }
    };
    processToAttach.stderr?.on("data", (data: Buffer | string) => {
      if (this.process !== processToAttach) {
        return;
      }

      consume(typeof data === "string" ? data : decoder.write(data));
    });
    processToAttach.on("exit", (code, signal) => {
      if (this.process !== processToAttach) {
        return;
      }
      consume(decoder.end(), true);

      if (this.status !== "stopped" && code !== 0) {
        this.status = "failed";
      }
      this.options.logs.emit(
        "encoder",
        code === 0 ? "info" : "error",
        `ffmpeg exited code=${code} signal=${signal}`
      );
    });
  }

  private maybeLowerBitrate(metrics: EncoderMetrics) {
    if (!this.options.adaptiveBitrate.enabled || metrics.speed === undefined) {
      return;
    }

    if (metrics.speed >= this.options.adaptiveBitrate.congestionSpeedThreshold) {
      this.congestionSamples = 0;
      return;
    }

    this.congestionSamples += 1;
    if (
      this.congestionSamples < this.options.adaptiveBitrate.congestionSampleCount
    ) {
      return;
    }

    this.congestionSamples = 0;
    const nextBitrate = lowerBitrate({
      current: this.currentVideoBitrate,
      minimum: this.options.adaptiveBitrate.minimumVideoBitrate,
      ratio: this.options.adaptiveBitrate.stepDownRatio
    });

    if (!nextBitrate || nextBitrate === this.currentVideoBitrate) {
      return;
    }

    const previousBitrate = this.currentVideoBitrate;
    this.currentVideoBitrate = nextBitrate;
    this.metrics = {
      ...this.metrics,
      ...bitrateMetrics(this.options.videoBitrate, nextBitrate)
    };
    this.status = "starting";
    this.options.logs.emit(
      "encoder",
      "warn",
      `encoder congestion detected; restarting ffmpeg at ${nextBitrate} from ${previousBitrate}`
    );
    this.process?.kill("SIGTERM");
    this.startProcess();
  }
}

export function buildFfmpegArgs(options: {
  rtmpUrl: string;
  display: string;
  width: number;
  height: number;
  fps: number;
  videoBitrate: string;
  videoCodec?: VideoCodec;
  audioEnabled?: boolean;
  audioCodec?: AudioCodec;
  audioSource?: string;
}) {
  const videoCodec = options.videoCodec ?? "h264";
  const audioCodec = options.audioCodec ?? "aac";
  const keyframeInterval = Math.max(1, options.fps * 2);
  const inputArgs = [
    "-hide_banner",
    "-loglevel",
    "info",
    "-stats",
    "-thread_queue_size",
    "16",
    "-f",
    "x11grab",
    "-draw_mouse",
    "0",
    "-video_size",
    `${options.width}x${options.height}`,
    "-framerate",
    String(options.fps),
    "-i",
    `${options.display}+0,0`
  ];
  const audioInputArgs = options.audioEnabled
    ? [
        "-thread_queue_size",
        "128",
        "-f",
        "pulse",
        "-sample_rate",
        "44100",
        "-channels",
        "2",
        "-i",
        options.audioSource ?? runtimeAudioSource
      ]
    : [];
  const audioOutputArgs = options.audioEnabled
    ? ["-map", "0:v:0", "-map", "1:a:0", "-af", "aresample=async=1", "-c:a", audioCodec, "-b:a", "128k", "-ar", "44100", "-ac", "2"]
    : ["-an"];

  if (audioCodec !== "aac") {
    throw new Error(`Unsupported RTMP/RTMPS live audio codec: ${audioCodec}`);
  }

  return [
    ...inputArgs,
    ...audioInputArgs,
    ...videoCodecArgs({
      codec: videoCodec,
      keyframeInterval
    }),
    "-pix_fmt",
    "yuv420p",
    "-g",
    String(keyframeInterval),
    "-keyint_min",
    String(keyframeInterval),
    "-sc_threshold",
    "0",
    "-b:v",
    options.videoBitrate,
    "-minrate",
    options.videoBitrate,
    "-maxrate",
    options.videoBitrate,
    "-bufsize",
    options.videoBitrate,
    ...audioOutputArgs,
    "-f",
    "flv",
    "-flvflags",
    "no_duration_filesize",
    "-rtmp_buffer",
    "100",
    "-tcp_nodelay",
    "1",
    options.rtmpUrl
  ];
}

export function parseFfmpegProgress(line: string): EncoderMetrics | undefined {
  if (!/^\s*frame=\s*[0-9]+\b/.test(line)) return undefined;
  const fps = extractNumber(line, /\bfps=\s*([0-9.]+)/);
  const bitrateKbps = extractNumber(line, /\bbitrate=\s*([0-9.]+)kbits\/s/);
  const droppedFrames = extractNumber(line, /\bdrop=\s*([0-9]+)/);
  const speed = extractNumber(line, /\bspeed=\s*([0-9.]+)x/);
  const metrics: EncoderMetrics = {};

  if (fps !== undefined) {
    metrics.fps = fps;
  }

  if (bitrateKbps !== undefined) {
    metrics.bitrateKbps = bitrateKbps;
  }

  if (droppedFrames !== undefined) {
    metrics.droppedFrames = droppedFrames;
  }

  if (speed !== undefined) {
    metrics.speed = speed;
  }

  return Object.keys(metrics).length > 0 ? metrics : undefined;
}

export function parseBitrateKbps(value: string) {
  const match = /^([0-9]+(?:\.[0-9]+)?)([kKmM]?)$/.exec(value.trim());

  if (!match) {
    return undefined;
  }

  const amount = Number(match[1]);
  const unit = match[2]?.toLowerCase();

  if (!Number.isFinite(amount)) {
    return undefined;
  }

  return Math.round(unit === "m" ? amount * 1000 : amount);
}

export function lowerBitrate(input: {
  current: string;
  minimum: string;
  ratio: number;
}) {
  const currentKbps = parseBitrateKbps(input.current);
  const minimumKbps = parseBitrateKbps(input.minimum);

  if (!currentKbps || !minimumKbps || input.ratio <= 0 || input.ratio >= 1) {
    return undefined;
  }

  const nextKbps = Math.max(
    minimumKbps,
    Math.floor(currentKbps * input.ratio)
  );

  if (nextKbps >= currentKbps) {
    return input.current;
  }

  return `${nextKbps}k`;
}

function bitrateMetrics(target: string, current: string): EncoderMetrics {
  const targetBitrateKbps = parseBitrateKbps(target);
  const currentBitrateKbps = parseBitrateKbps(current);
  return {
    ...(targetBitrateKbps !== undefined ? { targetBitrateKbps } : {}),
    ...(currentBitrateKbps !== undefined ? { currentBitrateKbps } : {})
  };
}

function videoCodecArgs(input: {
  codec: VideoCodec;
  keyframeInterval: number;
}) {
  switch (input.codec) {
    case "h264":
      return [
        "-c:v",
        "libx264",
        "-preset",
        "ultrafast",
        "-tune",
        "zerolatency",
        "-profile:v",
        "high",
        "-x264-params",
        `nal-hrd=cbr:force-cfr=1:keyint=${input.keyframeInterval}:min-keyint=${input.keyframeInterval}:scenecut=0`
      ];
    case "hevc":
      return [
        "-c:v",
        "libx265",
        "-preset",
        "ultrafast",
        "-tune",
        "zerolatency",
        "-x265-params",
        `nal-hrd=cbr:keyint=${input.keyframeInterval}:min-keyint=${input.keyframeInterval}:scenecut=0`
      ];
    case "av1":
      return [
        "-c:v",
        "libsvtav1",
        "-preset",
        "12",
        "-lag-in-frames",
        "0"
      ];
  }
}

function extractNumber(line: string, pattern: RegExp) {
  const match = pattern.exec(line);
  if (!match) {
    return undefined;
  }

  const parsed = Number(match[1]);
  return Number.isFinite(parsed) ? parsed : undefined;
}

import { spawn } from "node:child_process";
import {
  cp,
  mkdir,
  mkdtemp,
  readFile,
  readdir,
  readlink,
  rm,
  stat
} from "node:fs/promises";
import { createReadStream } from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import path from "node:path";
import { sdkIdentityForPackages } from "@repo/protocol/sdk-identity";
import { NPM_GAME_SDK_MANIFEST_PATH, readNpmGameSdkIdentity } from "@repo/protocol/npm-sdk-identity";

import type { ChildProcess, SpawnOptions } from "node:child_process";
import type { LogForwarder } from "./log-forwarder.js";
import type { ProcessLauncher } from "./xvfb.js";
import type { RuntimeGameSource } from "./supervisor.js";
import { downloadGameArchive, runPreparationProcess } from "./source-preparation.js";

export type TestableGameSource = RuntimeGameSource | { kind: "local_directory"; directory: string }
  | { kind: "git_archive"; archivePath: string; commitSha: string };
export const supportedGameContractVersion = "1.0.0";

export class GameServerController {
  private process: ChildProcess | undefined;
  private sourceDir: string | undefined;
  private preparedDirectory: string | undefined;
  private preparedIdentity: { kind: string; contentHash: string } | undefined;
  private processFailure: string | undefined;
  private stopping = false;
  private preparationController: AbortController | undefined;
  private preparation: Promise<unknown> | undefined;
  private preparationStage = "source selection";

  constructor(
    private readonly options: {
      port: number;
      controlWebSocketUrl: string;
      gameSource: TestableGameSource;
      repoRoot?: string;
      launcher?: ProcessLauncher;
      preparationLauncher?: ProcessLauncher;
      preparationTimeoutMs?: number;
      onSourcePrepared?: (directory: string) => Promise<void>;
      logs: LogForwarder;
    }
  ) {}

  get healthUrl() {
    return `http://127.0.0.1:${this.options.port}/healthz`;
  }

  get sourceDirectory() { return this.preparedDirectory; }
  get sourceIdentity() { return this.preparedIdentity; }

  async start() {
    const launcher = this.options.launcher ?? spawn;
    const command = process.platform === "win32" ? "corepack.cmd" : "corepack";
    const timeoutMs = this.options.preparationTimeoutMs ?? 300_000;
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) throw new Error("Source preparation timeout must be positive");
    this.stopping = false;
    const controller = new AbortController();
    this.preparationController = controller;
    const timer = setTimeout(() => {
      const failure = new Error(`Game source preparation timed out during ${this.preparationStage} after ${timeoutMs}ms`);
      this.options.logs.emit("game", "error", failure.message);
      controller.abort(failure);
    }, timeoutMs);
    const preparing = this.prepareGameSource(controller.signal);
    this.preparation = preparing;
    let source: Awaited<ReturnType<GameServerController["prepareGameSource"]>>;
    try {
      source = await preparing;
      controller.signal.throwIfAborted();
    } catch (error) {
      // Fetch and pipeline use their own AbortError; retain the useful stage/deadline.
      if (controller.signal.aborted) throw controller.signal.reason;
      throw error;
    } finally {
      clearTimeout(timer);
      this.preparation = undefined;
      this.preparationController = undefined;
    }
    this.preparedDirectory = source.cwd;
    const args =
      source.kind === "sample"
        ? ["pnpm", "--filter", source.sampleGameId, "dev:container"]
        : ["pnpm", "dev:container"];
    const spawnOptions: SpawnOptions = {
      cwd: source.cwd,
      env: buildGameProcessEnv({
        SAMPLE_GAME_PORT: String(this.options.port),
        VITE_CONTROL_WS_URL: this.options.controlWebSocketUrl
      }),
      stdio: "pipe",
      windowsHide: true,
      detached: process.platform !== "win32"
    };
    if (process.platform === "win32") spawnOptions.shell = true;

    this.stopping = false;
    this.processFailure = undefined;
    this.process = launcher(command, args, spawnOptions);
    this.attachLogs();
    this.options.logs.emit("game", "info", `${source.label} game server started`);
  }

  async waitUntilHealthy(timeoutMs = this.options.gameSource.kind === "sample" ? 30_000 : 120_000) {
    const deadline = Date.now() + timeoutMs;

    while (Date.now() < deadline) {
      this.assertProcessRunning();
      let healthy = false;
      try {
        const response = await fetch(this.healthUrl, { signal: AbortSignal.timeout(Math.min(1_000, Math.max(1, deadline - Date.now()))) });
        healthy = response.ok;
      } catch {
        // Keep polling until timeout.
      }
      this.assertProcessRunning();
      if (healthy) return;

      await wait(Math.min(250, Math.max(0, deadline - Date.now())));
    }

    this.assertProcessRunning();
    throw new Error(`game did not become healthy at ${this.healthUrl} within ${timeoutMs}ms`);
  }

  private assertProcessRunning() {
    if (this.processFailure) throw new Error(`Game process failed before readiness: ${this.processFailure}`);
    const child = this.process;
    if (child && (typeof child.exitCode === "number" || child.signalCode)) {
      throw new Error(`Game process exited before readiness code=${child.exitCode} signal=${child.signalCode}`);
    }
  }

  async stop() {
    this.stopping = true;
    this.preparationController?.abort(new Error(`Game source preparation cancelled during ${this.preparationStage}`));
    await this.preparation?.catch(() => undefined);
    const processToStop = this.process;
    if (processToStop?.pid && !this.options.launcher) {
      if (process.platform === "win32") {
        const killer = spawn("taskkill", ["/PID", String(processToStop.pid), "/T", "/F"], { windowsHide: true, stdio: "ignore" });
        await new Promise<void>(resolve => { killer.on("exit", () => resolve()); killer.on("error", () => resolve()); });
      } else {
        try { process.kill(-processToStop.pid, "SIGTERM"); } catch { processToStop.kill("SIGTERM"); }
      }
    } else processToStop?.kill("SIGTERM");
    if (processToStop?.pid && !this.options.launcher && processToStop.exitCode === null && processToStop.signalCode === null) {
      const exited = () => processToStop.exitCode !== null || processToStop.signalCode !== null;
      const deadline = Date.now() + 5000;
      while (!exited() && Date.now() < deadline) await wait(50);
      if (!exited()) {
        try { if (process.platform !== "win32") process.kill(-processToStop.pid, "SIGKILL"); else processToStop.kill("SIGKILL"); } catch { /* The exit event may be in flight. */ }
        const forcedDeadline = Date.now() + 2000;
        while (!exited() && Date.now() < forcedDeadline) await wait(50);
        if (!exited()) throw new Error("Game process did not exit after forced cleanup");
      }
    }
    this.process = undefined;
    if (this.sourceDir) {
      await rm(this.sourceDir, { recursive: true, force: true });
      this.sourceDir = undefined;
    }
  }

  private async prepareGameSource(signal: AbortSignal) {
    const stage = (name: string) => {
      signal.throwIfAborted();
      this.preparationStage = name;
      this.options.logs.emit("game", "info", `preparing game: ${name}`);
    };
    const sourcePrepared = async (cwd: string, manifestDirectory = cwd) => {
      signal.throwIfAborted();
      this.preparedDirectory = cwd;
      await this.options.onSourcePrepared?.(manifestDirectory);
      signal.throwIfAborted();
    };
    const install = async (cwd: string) => {
      // Validate committed metadata before lifecycle scripts, then verify both the
      // frozen identities and installed versions before launching any game code.
      const npmIdentity = await readNpmGameSdkIdentity(cwd, { verifyInstalled: false });
      const npmMetadata = npmIdentity ? await hashNpmSdkMetadata(cwd) : undefined;
      stage("dependency installation");
      await runPreparationProcess(process.platform === "win32" ? "corepack.cmd" : "corepack", ["pnpm", "install", "--frozen-lockfile"], {
        cwd, env: buildToolProcessEnv({}), signal, logs: this.options.logs,
        label: "Game dependency installation", ...(this.options.preparationLauncher ? { launcher: this.options.preparationLauncher } : {})
      });
      if (npmIdentity) {
        stage("installed npm SDK verification");
        if (await hashNpmSdkMetadata(cwd) !== npmMetadata) throw new Error("npm SDK metadata changed during frozen dependency installation");
        if (await readNpmGameSdkIdentity(cwd) !== npmIdentity) throw new Error("Installed npm SDK identity differs from the committed game identity");
        this.options.logs.emit("game", "info", `verified npm JavaScript SDK ${npmIdentity}`);
      }
    };
    if (this.options.gameSource.kind === "sample") {
      const sampleGameId = this.options.gameSource.sampleGameId ?? "sample-game";
      if (sampleGameId !== "sample-game") throw new Error("Only JavaScript games are supported; the Unity sample has been retired");
      this.preparedIdentity = { kind: "sample", contentHash: await hashGameSource(path.join(this.options.repoRoot ?? process.cwd(), "apps", sampleGameId), signal).catch(() => "unavailable") };
      await sourcePrepared(this.options.repoRoot ?? process.cwd(), path.join(this.options.repoRoot ?? process.cwd(), "apps", sampleGameId));
      return {
        kind: "sample" as const,
        sampleGameId,
        label: sampleGameId,
        cwd: this.options.repoRoot ?? process.cwd()
      };
    }

    if (this.options.gameSource.kind === "local_directory") {
      stage("local source copy");
      const original = path.resolve(this.options.gameSource.directory);
      const root = await mkdtemp(path.join(tmpdir(), "game-conformance-source-"));
      this.sourceDir = root;
      const cwd = path.join(root, "src");
      await cp(original, cwd, { recursive: true, filter: source => { signal.throwIfAborted(); return !path.relative(original, source).split(path.sep).some(part => ["node_modules", ".git", "dist", "artifacts", ".gameinstance"].includes(part)); } });
      this.preparedIdentity = { kind: "local_directory", contentHash: await hashGameSource(cwd, signal) };
      await sourcePrepared(cwd);
      stage("SDK verification");
      await hydrateStreamForgeSubmodules({ cwd, repoRoot: this.options.repoRoot ?? process.cwd(), logs: this.options.logs, signal });
      await install(cwd);
      return { kind: "local_directory" as const, label: "local conformance", cwd };
    }

    const root = await mkdtemp(path.join(tmpdir(), "game-source-"));
    const archivePath = path.join(root, "source.tar.gz");
    const extractDir = path.join(root, "src");
    await mkdir(extractDir, { recursive: true });
    this.sourceDir = root;

    if (this.options.gameSource.kind === "git_archive") {
      stage("archive copy");
      if (!/^[a-f0-9]{40}$/i.test(this.options.gameSource.commitSha)) throw new Error("Git archive requires an immutable commit SHA");
      await cp(this.options.gameSource.archivePath, archivePath);
    } else {
      stage("archive download");
      this.options.logs.emit("game", "info", `downloading game source ${this.options.gameSource.repositoryFullName ?? "github archive"}`);
      await downloadGameArchive(this.options.gameSource.archiveUrl, archivePath, signal);
    }
    this.preparedIdentity = { kind: this.options.gameSource.kind, contentHash: await hashFile(archivePath, signal) };
    stage("archive extraction");
    await runPreparationProcess("tar", ["-xzf", archivePath, "-C", extractDir], {
      cwd: root, env: buildToolProcessEnv({}), signal, logs: this.options.logs, label: "Game archive extraction",
      ...(this.options.preparationLauncher ? { launcher: this.options.preparationLauncher } : {})
    });

    const entries = await readdir(extractDir, { withFileTypes: true });
    const sourceRoot = entries.find((entry) => entry.isDirectory());
    if (!sourceRoot) {
      throw new Error("GitHub game archive did not contain a source directory");
    }

    const cwd = path.join(extractDir, sourceRoot.name);
    await sourcePrepared(cwd);
    stage("SDK verification");
    await hydrateStreamForgeSubmodules({
      cwd,
      repoRoot: this.options.repoRoot ?? process.cwd(),
      logs: this.options.logs,
      signal
    });

    this.options.logs.emit("game", "info", `installing game source ${sourceRoot.name}`);
    await install(cwd);

    return {
      kind: this.options.gameSource.kind,
      label: "github",
      cwd
    };
  }

  private attachLogs() {
    this.process?.stdout?.on("data", (data: Buffer | string) => {
      this.options.logs.emit("game", "info", String(data).trim());
    });
    this.process?.stderr?.on("data", (data: Buffer | string) => {
      for (const line of splitLogLines(data)) {
        if (this.stopping && isExpectedPnpmSigtermLine(line)) {
          continue;
        }

        this.options.logs.emit("game", "warn", line);
      }
    });
    this.process?.on("exit", (code, signal) => {
      this.processFailure = `exited code=${code} signal=${signal}`;
      const expectedShutdown = this.stopping && isExpectedShutdownExit(code, signal);
      this.options.logs.emit(
        "game",
        code === 0 || expectedShutdown ? "info" : "error",
        expectedShutdown
          ? `sample game stopped after shutdown request code=${code} signal=${signal}`
          : `sample game exited code=${code} signal=${signal}`
      );
    });
    this.process?.on("error", error => {
      this.processFailure = error.message;
      this.options.logs.emit("game", "error", error.message);
    });
  }
}

type StreamForgeSubmoduleManifest = {
  schemaVersion?: number;
  submodules?: Array<{
    path?: unknown;
    packages?: unknown;
    sdkIdentity?: unknown;
    distribution?: unknown;
    gameContractVersion?: unknown;
    sdkVersion?: unknown;
  }>;
};

export async function hydrateStreamForgeSubmodules(input: {
  cwd: string;
  repoRoot: string;
  logs: LogForwarder;
  signal?: AbortSignal;
}) {
  input.signal?.throwIfAborted();
  // npm games own their pinned tarballs; never hydrate an image SDK into them.
  if (await readNpmGameSdkIdentity(input.cwd, { verifyInstalled: false })) return;
  const manifestPath = path.join(input.cwd, ".streamforge-submodules.json");
  let manifest: StreamForgeSubmoduleManifest;

  try {
    manifest = JSON.parse(await readFile(manifestPath, "utf8"));
  } catch (error) {
    if (isFileNotFound(error)) {
      return;
    }

    throw error;
  }

  if (manifest.schemaVersion !== undefined && ![1, 2, 3].includes(manifest.schemaVersion as number)) throw new Error("Unsupported SDK manifest version");
  if (manifest.schemaVersion === 3 && (!Array.isArray(manifest.submodules) || manifest.submodules.length !== 1)) throw new Error("Bundled SDK manifest requires exactly one SDK");
  for (const submodule of manifest.submodules ?? []) {
    input.signal?.throwIfAborted();
    if (typeof submodule.path !== "string" || submodule.path.length === 0) {
      if (manifest.schemaVersion === 3) throw new Error("Bundled SDK path is missing");
      continue;
    }

    const packageNames = Array.isArray(submodule.packages)
      ? submodule.packages.filter(
          (value): value is string =>
            typeof value === "string" && value.length > 0
        )
      : ["game-kit", "protocol"];

    if (!packageNames.length || packageNames.some(name => !/^[a-z][a-z0-9-]*$/.test(name))) throw new Error("Invalid SDK package name");
    if (manifest.schemaVersion === 3) {
      if (submodule.distribution !== "bundled" || submodule.gameContractVersion !== supportedGameContractVersion || typeof submodule.sdkVersion !== "string") {
        throw new Error("Unsupported bundled SDK or game contract version");
      }
      if (typeof submodule.sdkIdentity !== "string" || !/^sha256:[a-f0-9]{64}$/.test(submodule.sdkIdentity)) throw new Error("Bundled SDK content identity is missing");
      if (["protocol", "game-kit", "game-dev"].some(name => !packageNames.includes(name))) throw new Error("Bundled SDK is missing a required package");
      const sdkRoot = resolveContainedPath(input.cwd, submodule.path);
      if (sdkIdentityForPackages(sdkRoot, packageNames).identity !== submodule.sdkIdentity) throw new Error("Bundled SDK content does not match its manifest");
      input.logs.emit("game", "info", `verified bundled JavaScript SDK ${submodule.sdkVersion}`);
      // The committed game owns this SDK. Never replace it with the image's copy.
      continue;
    }
    if (manifest.schemaVersion === 2) {
      if (typeof submodule.sdkIdentity !== "string" || !/^sha256:[a-f0-9]{64}$/.test(submodule.sdkIdentity)) {
        throw new Error("Game SDK content identity is missing; regenerate or repair the game manifest");
      }
      const submoduleRoot = resolveContainedPath(input.cwd, submodule.path);
      const supplied = await pathExists(path.join(submoduleRoot, "tsconfig.base.json"));
      const runtimeIdentity = sdkIdentityForPackages(input.repoRoot, packageNames).identity;
      const suppliedIdentity = supplied ? sdkIdentityForPackages(submoduleRoot, packageNames).identity : runtimeIdentity;
      if (runtimeIdentity !== submodule.sdkIdentity || suppliedIdentity !== submodule.sdkIdentity) throw new Error("Game SDK differs from the selected runtime image. Use a runtime built with the game's pinned SDK revision.");
    } else {
      input.logs.emit("game", "warn", "Legacy SDK manifest: package content identity is unverified");
    }

    await hydrateStreamForgeSubmodule({
      cwd: input.cwd,
      repoRoot: input.repoRoot,
      submodulePath: submodule.path,
      packageNames,
      logs: input.logs,
      ...(input.signal ? { signal: input.signal } : {})
    });
  }
}

export async function readGameSdkIdentity(cwd: string): Promise<string | undefined> {
  const npmIdentity = await readNpmGameSdkIdentity(cwd);
  if (npmIdentity) return npmIdentity;
  try {
    const manifest = JSON.parse(await readFile(path.join(cwd, ".streamforge-submodules.json"), "utf8")) as StreamForgeSubmoduleManifest;
    const entry = manifest.submodules?.[0];
    if (!entry || typeof entry.path !== "string" || !Array.isArray(entry.packages)) return undefined;
    return sdkIdentityForPackages(resolveContainedPath(cwd, entry.path), entry.packages as string[]).identity;
  } catch (error) { if (isFileNotFound(error)) return undefined; throw error; }
}

async function hashNpmSdkMetadata(cwd: string) {
  const contents = await Promise.all([NPM_GAME_SDK_MANIFEST_PATH, "package.json", "pnpm-lock.yaml"].map(file => readFile(path.join(cwd, file))));
  const digest = createHash("sha256");
  for (const content of contents) digest.update(String(content.length)).update(":").update(content);
  return digest.digest("hex");
}

async function hydrateStreamForgeSubmodule(input: {
  cwd: string;
  repoRoot: string;
  submodulePath: string;
  packageNames: string[];
  logs: LogForwarder;
  signal?: AbortSignal;
}) {
  const submoduleRoot = resolveContainedPath(input.cwd, input.submodulePath);
  const packagesRoot = path.join(submoduleRoot, "packages");
  const firstPackageJson = path.join(
    packagesRoot,
    input.packageNames[0] ?? "",
    "package.json"
  );

  if (await pathExists(firstPackageJson)) {
    return;
  }

  await mkdir(packagesRoot, { recursive: true });
  const baseConfig = path.join(input.repoRoot, "tsconfig.base.json");
  if (await pathExists(baseConfig)) await cp(baseConfig, path.join(submoduleRoot, "tsconfig.base.json"));

  for (const packageName of input.packageNames) {
    input.signal?.throwIfAborted();
    const source = path.join(input.repoRoot, "packages", packageName);
    const target = path.join(packagesRoot, packageName);

    if (await pathExists(path.join(target, "package.json"))) {
      continue;
    }

    await rm(target, { recursive: true, force: true });
    await cp(source, target, { recursive: true, filter: () => { input.signal?.throwIfAborted(); return true; } });
  }

  input.logs.emit(
    "game",
    "info",
    `hydrated StreamForge packages at ${path.relative(input.cwd, packagesRoot)}`
  );
}

function resolveContainedPath(root: string, relativePath: string) {
  const resolvedRoot = path.resolve(root);
  const resolvedPath = path.resolve(resolvedRoot, relativePath);

  if (
    resolvedPath !== resolvedRoot &&
    !resolvedPath.startsWith(`${resolvedRoot}${path.sep}`)
  ) {
    throw new Error(`Submodule path escapes game source: ${relativePath}`);
  }

  return resolvedPath;
}

async function pathExists(filePath: string) {
  try {
    await stat(filePath);
    return true;
  } catch (error) {
    if (isFileNotFound(error)) {
      return false;
    }

    throw error;
  }
}

function isFileNotFound(error: unknown) {
  return (
    error instanceof Error &&
    "code" in error &&
    (error as NodeJS.ErrnoException).code === "ENOENT"
  );
}

async function wait(ms: number) {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

async function hashFile(file: string, signal?: AbortSignal) {
  signal?.throwIfAborted();
  const digest = createHash("sha256");
  for await (const chunk of createReadStream(file, signal ? { signal } : {})) digest.update(chunk);
  return `sha256:${digest.digest("hex")}`;
}

export async function hashGameSource(directory: string, signal?: AbortSignal) {
  const files: Record<string, string> = {};
  const visit = async (folder: string) => {
    signal?.throwIfAborted();
    for (const entry of (await readdir(folder, { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name))) {
      if (["node_modules", ".git", "dist", "artifacts", ".gameinstance"].includes(entry.name)) continue;
      const file = path.join(folder, entry.name);
      const key = path.relative(directory, file).replaceAll("\\", "/");
      if (entry.isDirectory()) await visit(file);
      else files[key] = entry.isSymbolicLink() ? `symlink:${await readlink(file)}` : await hashFile(file, signal);
    }
  };
  await visit(directory);
  return `sha256:${createHash("sha256").update(JSON.stringify(files)).digest("hex")}`;
}

export function buildGameProcessEnv(extra: Record<string, string>) {
  return buildToolProcessEnv({
    ...extra,
    NODE_ENV: process.env.NODE_ENV ?? "development"
  });
}

export function buildToolProcessEnv(extra: Record<string, string>) {
  return {
    PATH: process.env.PATH ?? "",
    HOME: process.env.HOME ?? "/home/runtime",
    USER: process.env.USER ?? "runtime",
    TMPDIR: process.env.TMPDIR ?? tmpdir(),
    ...(process.platform === "win32" ? {
      SystemRoot: process.env.SystemRoot ?? "C:\\Windows",
      TEMP: process.env.TEMP ?? tmpdir(),
      TMP: process.env.TMP ?? tmpdir(),
      USERPROFILE: process.env.USERPROFILE ?? "",
      LOCALAPPDATA: process.env.LOCALAPPDATA ?? ""
    } : {}),
    npm_config_update_notifier: "false",
    ...extra
  };
}

function splitLogLines(data: Buffer | string) {
  return String(data)
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
}

function isExpectedPnpmSigtermLine(line: string) {
  return (
    line.includes("ERR_PNPM_RECURSIVE_RUN_FIRST_FAIL") &&
    line.includes('Command failed with signal "SIGTERM"')
  );
}

function isExpectedShutdownExit(
  code: number | null,
  signal: NodeJS.Signals | null
) {
  return signal === "SIGTERM" || code === 0 || code === 1;
}

