import type { RuntimeAgentLogEvent } from "@repo/protocol";

export type RuntimeIdentity = {
  streamId: string;
  deploymentId: string;
  runtimeInstanceId: string;
};

export type RuntimeLogSource =
  | "runtime"
  | "game"
  | "renderer"
  | "encoder"
  | "control-agent"
  | "xvfb";

export type RuntimeLogSink = (event: RuntimeAgentLogEvent) => void;

export class LogForwarder {
  constructor(
    private readonly identity: RuntimeIdentity,
    private readonly sink: RuntimeLogSink,
    private readonly now: () => string = () => new Date().toISOString()
  ) {}

  emit(
    source: RuntimeLogSource,
    level: RuntimeAgentLogEvent["level"],
    message: string
  ) {
    this.sink({
      type: "runtime.log",
      streamId: this.identity.streamId,
      deploymentId: this.identity.deploymentId,
      runtimeInstanceId: this.identity.runtimeInstanceId,
      source,
      level,
      message: redact(message),
      timestamp: this.now()
    });
  }
}

export function redact(value: string) {
  return value
    .replace(/rtmps?:\/\/\S+/gi, "[REDACTED_RTMP_URL]")
    .replace(/https:\/\/codeload\.github\.com\/\S+/gi, "[REDACTED_GITHUB_ARCHIVE_URL]")
    .replace(/(GAME_SOURCE_ARCHIVE_URL=)\S+/gi, "$1[REDACTED]")
    .replace(/(authorization:\s*bearer\s+)\S+/gi, "$1[REDACTED]")
    .replace(/([A-Z0-9_]*(SECRET|TOKEN|PASSWORD|KEY)[A-Z0-9_]*=)\S+/gi, "$1[REDACTED]")
    .replace(/(DATABASE_URL=)\S+/gi, "$1[REDACTED]");
}

/** Never inherit control-plane credentials or stream keys into child processes. */
export function buildRuntimeChildEnv(extra: Record<string, string> = {}) {
  const env: Record<string, string> = {};
  for (const key of ["PATH", "HOME", "USER", "TMPDIR", "TMP", "TEMP", "SystemRoot", "WINDIR", "LANG", "LC_ALL", "LD_LIBRARY_PATH", "XAUTHORITY", "XDG_RUNTIME_DIR", "PULSE_SERVER", "SSL_CERT_FILE", "SSL_CERT_DIR"]) {
    if (process.env[key] !== undefined) env[key] = process.env[key]!;
  }
  return { ...env, ...extra };
}

