import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { chromium } from "playwright";
import { buildRuntimeChildEnv } from "./process-env.js";

import type { BrowserContext, Page } from "playwright";
import type { LogForwarder } from "./log-forwarder.js";

export const chromiumIgnoreDefaultArgs = ["--enable-automation"] as const;

export type RendererStatus =
  | "not_started"
  | "starting"
  | "ready"
  | "crashed"
  | "stopped";

export class RendererController {
  private context: BrowserContext | undefined;
  private page: Page | undefined;
  private userDataDir: string | undefined;
  status: RendererStatus = "not_started";

  constructor(
    private readonly options: {
      gameUrl: string;
      display: string;
      width: number;
      height: number;
      audioEnvironment?: Readonly<Record<string, string>>;
      logs: LogForwarder;
    }
  ) {}

  async start() {
    this.status = "starting";
    this.userDataDir = await mkdtemp(
      path.join(tmpdir(), "stream-runtime-chromium-")
    );
    this.context = await chromium.launchPersistentContext(this.userDataDir, {
      headless: false,
      chromiumSandbox: false,
      ignoreDefaultArgs: [...chromiumIgnoreDefaultArgs],
      env: buildRuntimeChildEnv({ DISPLAY: this.options.display, ...this.options.audioEnvironment }),
      args: buildChromiumArgs({
        gameUrl: this.options.gameUrl,
        width: this.options.width,
        height: this.options.height
      }),
      viewport: {
        width: this.options.width,
        height: this.options.height
      },
      screen: {
        width: this.options.width,
        height: this.options.height
      },
      deviceScaleFactor: 1
    });

    this.page =
      this.context.pages()[0] ??
      (await this.context
        .waitForEvent("page", { timeout: 5_000 })
        .catch(() => undefined)) ??
      (await this.context.newPage());
    this.attachLogs(this.page);
    await this.page.goto(this.options.gameUrl, { waitUntil: "domcontentloaded" });
    await this.page.waitForFunction(
      () =>
        (window as Window & { __STREAM_READY__?: boolean }).__STREAM_READY__ ===
        true,
      undefined,
      { timeout: 60_000 }
    );
    this.status = "ready";
    this.options.logs.emit("renderer", "info", "renderer ready");
  }

  async stop() {
    let firstError: Error | undefined;
    for (const [name, close] of [
      ["page", () => this.page?.close()],
      ["browser context", () => this.context?.close()],
      ["profile directory", () => this.cleanupUserDataDir()]
    ] as const) {
      try { await boundedRendererAction(`${name} cleanup`, close); }
      catch (error) { firstError ??= error instanceof Error ? error : new Error(String(error)); }
    }
    this.page = undefined;
    this.context = undefined;
    this.status = "stopped";
    if (firstError) throw firstError;
  }

  async captureDiagnostics(screenshotPath: string) {
    const page = this.page;
    if (!page) throw new Error("Renderer has not started");
    // A game's infinite loop can stall both operations. An outer deadline also
    // covers evaluate, whose Playwright API has no per-call timeout option.
    return boundedRendererAction("diagnostics", async () => {
      await page.screenshot({ path: screenshotPath, timeout: 5_000 });
      return page.evaluate(() => ({
        ready: (window as Window & { __STREAM_READY__?: boolean }).__STREAM_READY__ === true,
        title: document.title,
        localInspectorVisible: Boolean(document.querySelector("[data-gameinstance-devtools]"))
      }));
    });
  }

  private attachLogs(page: Page) {
    page.on("console", (message) => {
      this.options.logs.emit("renderer", "info", message.text());
    });
    page.on("pageerror", (error) => {
      this.options.logs.emit("renderer", "error", error.message);
    });
    page.on("crash", () => {
      this.status = "crashed";
      this.options.logs.emit("renderer", "error", "renderer page crashed");
    });
  }

  private async cleanupUserDataDir() {
    const directory = this.userDataDir;
    this.userDataDir = undefined;

    if (directory) {
      await rm(directory, { recursive: true, force: true });
    }
  }
}

async function boundedRendererAction<T>(name: string, action: () => Promise<T> | T) {
  let timeout: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      Promise.resolve().then(action),
      new Promise<never>((_, reject) => { timeout = setTimeout(() => reject(new Error(`Renderer ${name} timed out`)), 5_000); })
    ]);
  } finally { clearTimeout(timeout); }
}

export function buildChromiumArgs(input: {
  gameUrl: string;
  width: number;
  height: number;
}) {
  return [
    `--app=${input.gameUrl}`,
    "--kiosk",
    "--start-fullscreen",
    "--autoplay-policy=no-user-gesture-required",
    "--disable-background-networking",
    "--disable-background-timer-throttling",
    "--disable-dev-shm-usage",
    "--disable-extensions",
    "--disable-infobars",
    "--disable-renderer-backgrounding",
    "--force-color-profile=srgb",
    "--force-device-scale-factor=1",
    "--hide-scrollbars",
    "--no-first-run",
    "--no-default-browser-check",
    "--window-position=0,0",
    `--window-size=${input.width},${input.height}`
  ];
}

