import {
  GameCommandResultSchema,
  chatEventToGameCommand,
  subscriberEventToGameCommand,
  RuntimeChatMessageSchema,
  RuntimeCommandMessageSchema,
  RuntimeSubscriberMessageSchema,
  RuntimeRegistrationSchema
} from "@repo/protocol";
import WebSocket, { WebSocketServer } from "ws";

import type {
  GameCommand,
  GameCommandResult,
  NormalizedChatEvent,
  NormalizedSubscriberEvent,
  RuntimeAgentHeartbeat,
  RuntimeAgentLogEvent,
  RuntimeRegistration
} from "@repo/protocol";
import type { LogForwarder, RuntimeIdentity } from "./log-forwarder.js";

export type RuntimeControlAgentStatus =
  | "starting"
  | "connected"
  | "disconnected"
  | "stopping";

export type RuntimeControlTransportPolicy = Readonly<{
  local: true;
  nodeEnvironment: "development";
}>;

/** Only the trusted worker's explicit local policy can enable the Compose bridge. */
export function loadRuntimeControlTransportPolicy(
  env: Readonly<Record<string, string | undefined>>
): RuntimeControlTransportPolicy | undefined {
  const local = env.GAMEGO_LOCAL;
  if (local !== undefined && local !== "false" && local !== "true") throw new Error("Invalid local runtime control policy");
  if (local !== "true") return undefined;
  if (env.NODE_ENV !== "development") {
    throw new Error("Invalid local runtime control policy");
  }
  return { local: true, nodeEnvironment: "development" };
}

export class RuntimeControlAgent {
  private orchestratorSocket: WebSocket | undefined;
  private gameSocket: WebSocket | undefined;
  private bridgeServer: WebSocketServer | undefined;
  private stopped = false;
  private reconnectTimer: ReturnType<typeof setTimeout> | undefined;
  private reconnectAttempt = 0;
  private initialConnectionResolve: (() => void) | undefined;
  private initialConnectionReject: ((error: Error) => void) | undefined;
  status: RuntimeControlAgentStatus = "starting";

  constructor(
    private readonly options: {
      identity: RuntimeIdentity;
      runtimeVersion: string;
      orchestratorRuntimeWsUrl: string;
      gameControlPort: number;
      workerId?: string;
      containerId?: string;
      runtimeAuthToken?: string;
      transportPolicy?: RuntimeControlTransportPolicy;
      reconnectDelayMs?: number;
      maxReconnectDelayMs?: number;
      startedAt: string;
      logs: LogForwarder;
    }
  ) {}

  get gameControlUrl() {
    const address = this.bridgeServer?.address();
    const port = address && typeof address !== "string" ? address.port : this.options.gameControlPort;
    return `ws://127.0.0.1:${port}/runtime/${this.options.identity.runtimeInstanceId}`;
  }

  async start() {
    const connectionOptions = runtimeControlSocketOptions(
      this.options.orchestratorRuntimeWsUrl, this.options.runtimeAuthToken, this.options.transportPolicy
    );
    this.stopped = false;
    this.bridgeServer = new WebSocketServer({
      host: "127.0.0.1",
      port: this.options.gameControlPort
    });
    this.bridgeServer.on("connection", (socket) => {
      this.gameSocket = socket;
      socket.on("message", (data) => this.handleGameMessage(data));
    });

    await new Promise<void>((resolve, reject) => {
      this.initialConnectionResolve = resolve;
      this.initialConnectionReject = reject;
      this.connect(connectionOptions);
    });
  }

  private connect(connectionOptions: WebSocket.ClientOptions) {
    if (this.stopped) return;
    let socket: WebSocket;
    try { socket = new WebSocket(this.options.orchestratorRuntimeWsUrl, connectionOptions); }
    catch {
      this.initialConnectionReject?.(new Error("Unable to initialize runtime control connection"));
      this.initialConnectionResolve = undefined;
      this.initialConnectionReject = undefined;
      return;
    }
    this.orchestratorSocket = socket;
    socket.on("open", () => {
      if (this.stopped || this.orchestratorSocket !== socket) { socket.close(); return; }
      this.status = "connected";
      this.reconnectAttempt = 0;
      this.sendRegistration();
      this.initialConnectionResolve?.();
      this.initialConnectionResolve = undefined;
      this.initialConnectionReject = undefined;
    });
    socket.on("message", (data) => {
      if (!this.stopped && this.orchestratorSocket === socket) this.handleOrchestratorMessage(data);
    });
    socket.on("error", () => {
      // Never forward handshake details: they may contain request headers.
      socket.close();
    });
    socket.on("close", () => {
      if (this.orchestratorSocket !== socket) return;
      this.orchestratorSocket = undefined;
      if (this.stopped) return;
      this.status = "disconnected";
      this.scheduleReconnect(connectionOptions);
    });
  }

  private scheduleReconnect(connectionOptions: WebSocket.ClientOptions) {
    if (this.stopped || this.reconnectTimer) return;
    const base = Math.max(1, this.options.reconnectDelayMs ?? 1000);
    const maximum = Math.max(base, this.options.maxReconnectDelayMs ?? 30000);
    const delay = Math.min(maximum, base * 2 ** Math.min(this.reconnectAttempt++, 20));
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = undefined;
      this.connect(connectionOptions);
    }, delay);
    this.reconnectTimer.unref?.();
  }

  sendHeartbeat(heartbeat: RuntimeAgentHeartbeat) {
    this.sendToOrchestrator(heartbeat);
  }

  sendLog(log: RuntimeAgentLogEvent) {
    this.sendToOrchestrator(log);
  }

  async stop() {
    this.stopped = true;
    this.status = "stopping";
    if (this.reconnectTimer) { clearTimeout(this.reconnectTimer); this.reconnectTimer = undefined; }
    this.initialConnectionReject?.(new Error("Runtime control stopped before connecting"));
    this.initialConnectionResolve = undefined;
    this.initialConnectionReject = undefined;
    this.gameSocket?.close();
    this.orchestratorSocket?.close();
    await new Promise<void>((resolve) => {
      this.bridgeServer?.close(() => resolve());
      if (!this.bridgeServer) {
        resolve();
      }
    });
  }

  private sendRegistration() {
    const registration = RuntimeRegistrationSchema.parse({
      type: "runtime.register",
      ...this.options.identity,
      ...(this.options.workerId ? { workerId: this.options.workerId } : {}),
      ...(this.options.containerId ? { containerId: this.options.containerId } : {}),
      runtimeVersion: this.options.runtimeVersion,
      startedAt: this.options.startedAt
    } satisfies RuntimeRegistration);

    this.sendToOrchestrator(registration);
  }

  private handleOrchestratorMessage(data: WebSocket.RawData) {
    let parsedJson: unknown;
    try { parsedJson = JSON.parse(String(data)); } catch { return; }
    const command = RuntimeCommandMessageSchema.safeParse(parsedJson);
    if (command.success) {
      this.sendGameCommand(command.data.command);
      return;
    }

    const chat = RuntimeChatMessageSchema.safeParse(parsedJson);
    if (chat.success) {
      this.sendChat(chat.data.event);
      return;
    }

    const subscriber = RuntimeSubscriberMessageSchema.safeParse(parsedJson);
    if (subscriber.success) {
      this.sendSubscriber(subscriber.data.event);
    }
  }

  private handleGameMessage(data: WebSocket.RawData) {
    let parsed: unknown;
    try { parsed = JSON.parse(String(data)); } catch { return; }
    const result = GameCommandResultSchema.safeParse(parsed);

    if (result.success) {
      this.sendToOrchestrator({
        type: "runtime.commandResult",
        result: result.data
      });
    }
  }

  private sendGameCommand(command: GameCommand) {
    if (command.streamId !== this.options.identity.streamId || command.deploymentId !== this.options.identity.deploymentId || command.runtimeInstanceId !== this.options.identity.runtimeInstanceId) return;
    if (this.gameSocket?.readyState === WebSocket.OPEN) this.gameSocket.send(JSON.stringify(command));
  }

  private sendChat(chatEvent: NormalizedChatEvent) {
    try { this.sendGameCommand(chatEventToGameCommand(chatEvent, this.options.identity)); } catch { /* Ignore events scoped to another session. */ }
  }

  private sendSubscriber(subscriberEvent: NormalizedSubscriberEvent) {
    try { this.sendGameCommand(subscriberEventToGameCommand(subscriberEvent, this.options.identity)); } catch { /* Ignore events scoped to another session. */ }
  }

  private sendToOrchestrator(message: unknown) {
    if (this.orchestratorSocket?.readyState === WebSocket.OPEN) {
      this.orchestratorSocket.send(JSON.stringify(message));
    }
  }
}

export function runtimeControlSocketOptions(
  urlString: string, token?: string, policy?: RuntimeControlTransportPolicy
): WebSocket.ClientOptions {
  if (!token) return { followRedirects: false, handshakeTimeout: 15000 };
  if (!/^[a-zA-Z0-9_.~-]{32,256}$/.test(token)) throw new Error("Invalid runtime control credential");
  let url: URL;
  try { url = new URL(urlString); } catch { throw new Error("Invalid runtime control URL"); }
  const loopback = url.hostname === "127.0.0.1" || url.hostname === "[::1]";
  // Do not normalize this exception: alternate hosts, ports, paths, credentials,
  // query strings and even equivalent URL spellings must retain TLS enforcement.
  const privateLocal = policy?.nodeEnvironment === "development" && policy.local === true &&
    urlString === "ws://orchestrator:4100/runtimes/ws";
  if ((url.protocol !== "wss:" && !(loopback && url.protocol === "ws:") && !privateLocal) || url.username || url.password || url.search || url.hash) {
    throw new Error("Authenticated runtime control requires TLS (literal loopback is allowed for development)");
  }
  return { headers: { Authorization: `Bearer ${token}` }, followRedirects: false, handshakeTimeout: 15000 };
}

