export type Stoppable = {
  stop(): Promise<void>;
};

export async function startWithCleanup(component: Stoppable & { start(): Promise<void> }) {
  try { await component.start(); }
  catch (startupError) {
    try { await component.stop(); }
    catch (cleanupError) { throw new AggregateError([startupError, cleanupError], "Runtime startup and cleanup failed"); }
    throw startupError;
  }
}

export async function stopInOrder(components: readonly Stoppable[]) {
  let firstError: Error | undefined;
  for (const component of components) {
    try { await component.stop(); }
    catch (error) { firstError ??= error instanceof Error ? error : new Error(String(error)); }
  }
  if (firstError) throw firstError;
}

