import { spawn, type ChildProcess, type SpawnOptions } from "node:child_process";
import { createWriteStream } from "node:fs";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import type { LogForwarder } from "./log-forwarder.js";
import type { ProcessLauncher } from "./xvfb.js";

/** Fetch and disk writes share the preparation deadline, including a stalled body. */
export async function downloadGameArchive(url: string, targetPath: string, signal: AbortSignal) {
  const response = await fetch(url, { signal });
  if (!response.ok || !response.body) throw new Error(`Game source download failed with ${response.status}`);
  await pipeline(Readable.fromWeb(response.body as import("node:stream/web").ReadableStream), createWriteStream(targetPath), { signal });
}

/** A package script can spawn children; cancelling only pnpm leaves those running. */
export async function terminateProcessTree(child: ChildProcess, injectedLauncher = false) {
  if (!child.pid || injectedLauncher) { child.kill("SIGKILL"); return; }
  if (process.platform === "win32") {
    const killer = spawn("taskkill", ["/PID", String(child.pid), "/T", "/F"], { windowsHide: true, stdio: "ignore" });
    await new Promise<void>(resolve => {
      const timer = setTimeout(() => { killer.kill(); child.kill("SIGKILL"); resolve(); }, 5_000);
      const done = () => { clearTimeout(timer); resolve(); };
      killer.once("exit", done); killer.once("error", done);
    });
  } else {
    // Preparation processes have their own group. SIGKILL also reaches scripts that
    // ignore TERM, or descendants holding stdout open after their parent exits.
    try { process.kill(-child.pid, "SIGKILL"); } catch { child.kill("SIGKILL"); }
  }
}

export async function runPreparationProcess(command: string, args: readonly string[], options: {
  cwd: SpawnOptions["cwd"];
  env: NodeJS.ProcessEnv;
  signal: AbortSignal;
  logs: LogForwarder;
  label: string;
  launcher?: ProcessLauncher;
}) {
  options.signal.throwIfAborted();
  const child = (options.launcher ?? spawn)(command, [...args], {
    cwd: options.cwd, env: options.env, stdio: ["ignore", "pipe", "pipe"],
    // Only command shims require cmd.exe. Executables and their arguments stay literal.
    shell: process.platform === "win32" && /\.(?:cmd|bat)$/i.test(command),
    detached: process.platform !== "win32", windowsHide: true
  });
  let stderr = "";
  child.stderr?.on("data", (data: Buffer | string) => {
    stderr = (stderr + String(data)).slice(-8_192);
    options.logs.emit("game", "warn", `${options.label}: ${String(data).trim().slice(-2_048)}`);
  });
  child.stdout?.on("data", (data: Buffer | string) => {
    options.logs.emit("game", "info", `${options.label}: ${String(data).trim().slice(-2_048)}`);
  });
  await new Promise<void>((resolve, reject) => {
    let settled = false;
    const finish = (error?: Error) => {
      if (settled) return;
      settled = true;
      options.signal.removeEventListener("abort", abort);
      if (error) reject(error); else resolve();
    };
    const abort = () => {
      // Keep the promise pending until the whole process tree has been terminated.
      void terminateProcessTree(child, Boolean(options.launcher)).then(() => {
        finish(options.signal.reason instanceof Error ? options.signal.reason : new Error(`${options.label} cancelled`));
      }, error => finish(error instanceof Error ? error : new Error(String(error))));
    };
    child.once("error", error => { if (!options.signal.aborted) finish(error); });
    child.once("close", code => {
      if (options.signal.aborted) return;
      finish(code === 0 ? undefined : new Error(`${options.label} failed (exit ${code}): ${stderr.trim()}`));
    });
    options.signal.addEventListener("abort", abort, { once: true });
    if (options.signal.aborted) abort();
  });
}

