import { AudioController, runtimeAudioEnvironment } from "./audio-controller.js";
import { EncoderController } from "./encoder-controller.js";
import { GameServerController } from "./game-server.js";
import { LogForwarder } from "./log-forwarder.js";
import { RendererController } from "./renderer-controller.js";
import { RuntimeControlAgent, loadRuntimeControlTransportPolicy, type RuntimeControlTransportPolicy } from "./runtime-control-agent.js";
import { stopInOrder } from "./shutdown.js";
import { XvfbController } from "./xvfb.js";

import type { RuntimeAgentHeartbeat } from "@repo/protocol";
import type {
  AdaptiveBitrateOptions,
  AudioCodec,
  EncoderMetrics,
  VideoCodec
} from "./encoder-controller.js";
import type { RuntimeIdentity, RuntimeLogSink } from "./log-forwarder.js";

export type RuntimeEnv = {
  streamId: string;
  deploymentId: string;
  runtimeInstanceId: string;
  orchestratorRuntimeWsUrl: string;
  rtmpUrl: string;
  streamWidth: number;
  streamHeight: number;
  streamFps: number;
  videoBitrate: string;
  videoCodec: VideoCodec;
  audioEnabled: boolean;
  audioCodec: AudioCodec;
  adaptiveBitrate: AdaptiveBitrateOptions;
  gamePort: number;
  gameControlWsPort: number;
  gameSource: RuntimeGameSource;
  display: string;
  workerId?: string;
  containerId?: string;
  runtimeAuthToken?: string;
  runtimeControlTransportPolicy?: RuntimeControlTransportPolicy;
};

export type RuntimeGameSource =
  | { kind: "sample"; sampleGameId?: "sample-game" | "sample-game-unity" }
  | {
      kind: "github_archive";
      archiveUrl: string;
      repositoryFullName?: string;
      ref?: string;
      commitSha?: string;
    };

export type RuntimeComponent = {
  start(): Promise<void>;
  stop(): Promise<void>;
};

export type RuntimeComponents = {
  controlAgent: RuntimeComponent & {
    status: RuntimeAgentHeartbeat["controlAgent"]["status"];
    sendHeartbeat(heartbeat: RuntimeAgentHeartbeat): void;
    sendLog(event: Parameters<RuntimeLogSink>[0]): void;
  };
  xvfb: RuntimeComponent;
  audio?: RuntimeComponent & { status?: string };
  game: RuntimeComponent & {
    healthUrl: string;
    waitUntilHealthy(): Promise<void>;
  };
  renderer: RuntimeComponent & {
    status: RuntimeAgentHeartbeat["renderer"]["status"];
  };
  encoder: RuntimeComponent & {
    status: RuntimeAgentHeartbeat["encoder"]["status"];
    metrics: EncoderMetrics;
  };
};

export type StreamRuntimeSupervisorOptions = {
  env?: NodeJS.ProcessEnv;
  now?: () => string;
  runtimeVersion?: string;
  logSink?: RuntimeLogSink;
  componentFactory?: (
    env: RuntimeEnv,
    logs: LogForwarder
  ) => RuntimeComponents;
};

export class StreamRuntimeSupervisor {
  private readonly env: RuntimeEnv;
  private readonly now: () => string;
  private readonly logs: LogForwarder;
  private readonly components: RuntimeComponents;
  private status: RuntimeAgentHeartbeat["status"] = "provisioning";
  private heartbeatTimer: ReturnType<typeof setInterval> | undefined;

  constructor(private readonly options: StreamRuntimeSupervisorOptions = {}) {
    this.env = loadRuntimeEnv(options.env ?? process.env);
    this.now = options.now ?? (() => new Date().toISOString());
    const identity = runtimeIdentity(this.env);
    this.logs = new LogForwarder(
      identity,
      (event) => {
        this.components?.controlAgent.sendLog(event);
        options.logSink?.(event);
      },
      this.now
    );
    this.components =
      options.componentFactory?.(this.env, this.logs) ??
      createDefaultComponents(
        this.env,
        this.logs,
        options.runtimeVersion ?? "0.1.0",
        this.now
      );
  }

  async start() {
    await this.components.controlAgent.start();
    this.emitHeartbeat("provisioning");

    await this.components.xvfb.start();
    await this.components.audio?.start();
    await this.components.game.start();
    this.emitHeartbeat("starting_game_server");
    await this.components.game.waitUntilHealthy();

    await this.components.renderer.start();
    this.emitHeartbeat("starting_renderer");

    await this.components.encoder.start();
    this.emitHeartbeat("starting_encoder");

    this.emitHeartbeat("healthy");
    this.startHeartbeatLoop();
  }

  async stop() {
    this.stopHeartbeatLoop();
    this.emitHeartbeat("stopping");
    await stopInOrder([
      this.components.encoder,
      this.components.renderer,
      this.components.game,
      ...(this.components.audio ? [this.components.audio] : []),
      this.components.xvfb,
      this.components.controlAgent
    ]);
    this.emitHeartbeat("stopped");
  }

  private emitHeartbeat(status: RuntimeAgentHeartbeat["status"]) {
    this.status = status;
    this.components.controlAgent.sendHeartbeat(this.buildHeartbeat());
  }

  private startHeartbeatLoop() {
    if (this.heartbeatTimer) {
      return;
    }

    this.heartbeatTimer = setInterval(() => {
      this.components.controlAgent.sendHeartbeat(this.buildHeartbeat());
    }, 5000);
  }

  private stopHeartbeatLoop() {
    if (!this.heartbeatTimer) {
      return;
    }

    clearInterval(this.heartbeatTimer);
    this.heartbeatTimer = undefined;
  }

  private buildHeartbeat(): RuntimeAgentHeartbeat {
    const audioFailed = this.status === "healthy" && this.components.audio?.status === "failed";
    return {
      type: "runtime.heartbeat",
      ...runtimeIdentity(this.env),
      timestamp: this.now(),
      status: audioFailed ? "degraded" : this.status,
      game: {
        status:
          this.status === "starting_game_server" ? "starting" : "healthy",
        healthUrl: this.components.game.healthUrl
      },
      renderer: {
        status: this.components.renderer.status
      },
      encoder: {
        status: this.components.encoder.status,
        ...this.components.encoder.metrics,
        ...(audioFailed ? { lastError: "Game audio capture failed" } : {})
      },
      controlAgent: {
        status: this.components.controlAgent.status
      }
    };
  }
}

export function loadRuntimeEnv(env: NodeJS.ProcessEnv): RuntimeEnv {
  const required = [
    "STREAM_ID",
    "DEPLOYMENT_ID",
    "RUNTIME_INSTANCE_ID",
    "ORCHESTRATOR_RUNTIME_WS_URL",
    "RTMP_URL",
    "STREAM_WIDTH",
    "STREAM_HEIGHT",
    "STREAM_FPS",
    "VIDEO_BITRATE",
    "AUDIO_ENABLED"
  ];
  const missing = required.filter((key) => !env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required runtime env vars: ${missing.join(", ")}`);
  }

  const runtimeControlTransportPolicy = loadRuntimeControlTransportPolicy(env);

  return {
    streamId: env.STREAM_ID!,
    deploymentId: env.DEPLOYMENT_ID!,
    runtimeInstanceId: env.RUNTIME_INSTANCE_ID!,
    orchestratorRuntimeWsUrl: env.ORCHESTRATOR_RUNTIME_WS_URL!,
    rtmpUrl: env.RTMP_URL!,
    streamWidth: parsePositiveInt(env.STREAM_WIDTH!, "STREAM_WIDTH"),
    streamHeight: parsePositiveInt(env.STREAM_HEIGHT!, "STREAM_HEIGHT"),
    streamFps: parsePositiveInt(env.STREAM_FPS!, "STREAM_FPS"),
    videoBitrate: env.VIDEO_BITRATE!,
    videoCodec: parseVideoCodec(env.VIDEO_CODEC ?? "h264"),
    audioEnabled: env.AUDIO_ENABLED === "true",
    audioCodec: parseAudioCodec(env.AUDIO_CODEC ?? "aac"),
    adaptiveBitrate: parseAdaptiveBitrate(env),
    gamePort: parsePositiveInt(env.GAME_PORT ?? "5173", "GAME_PORT"),
    gameControlWsPort: parsePositiveInt(
      env.GAME_CONTROL_WS_PORT ?? "8787",
      "GAME_CONTROL_WS_PORT"
    ),
    gameSource: parseRuntimeGameSource(env),
    display: env.DISPLAY ?? ":99",
    ...(env.WORKER_ID ? { workerId: env.WORKER_ID } : {}),
    ...(env.RUNTIME_AUTH_TOKEN ? { runtimeAuthToken: env.RUNTIME_AUTH_TOKEN } : {}),
    ...(runtimeControlTransportPolicy ? { runtimeControlTransportPolicy } : {}),
    ...(env.CONTAINER_ID ? { containerId: env.CONTAINER_ID } : {})
  };
}

function createDefaultComponents(
  env: RuntimeEnv,
  logs: LogForwarder,
  runtimeVersion: string,
  now: () => string
): RuntimeComponents {
  const identity = runtimeIdentity(env);
  const controlAgent = new RuntimeControlAgent({
    identity,
    runtimeVersion,
    orchestratorRuntimeWsUrl: env.orchestratorRuntimeWsUrl,
    gameControlPort: env.gameControlWsPort,
    startedAt: now(),
    ...(env.workerId ? { workerId: env.workerId } : {}),
    ...(env.runtimeAuthToken ? { runtimeAuthToken: env.runtimeAuthToken } : {}),
    ...(env.runtimeControlTransportPolicy ? { transportPolicy: env.runtimeControlTransportPolicy } : {}),
    ...(env.containerId ? { containerId: env.containerId } : {}),
    logs
  });
  const game = new GameServerController({
    port: env.gamePort,
    controlWebSocketUrl: controlAgent.gameControlUrl,
    gameSource: env.gameSource,
    logs
  });
  const audio = env.audioEnabled ? new AudioController({ logs }) : undefined;
  const audioOptions = audio ? { audioEnvironment: runtimeAudioEnvironment } : {};
  const renderer = new RendererController({
    gameUrl: `http://127.0.0.1:${env.gamePort}`,
    display: env.display,
    width: env.streamWidth,
    height: env.streamHeight,
    ...audioOptions,
    logs
  });
  const encoder = new EncoderController({
    rtmpUrl: env.rtmpUrl,
    display: env.display,
    width: env.streamWidth,
    height: env.streamHeight,
    fps: env.streamFps,
    videoBitrate: env.videoBitrate,
    videoCodec: env.videoCodec,
    audioEnabled: env.audioEnabled,
    audioCodec: env.audioCodec,
    ...audioOptions,
    adaptiveBitrate: env.adaptiveBitrate,
    logs
  });
  const xvfb = new XvfbController({
    display: env.display,
    width: env.streamWidth,
    height: env.streamHeight,
    logs
  });

  return {
    controlAgent,
    xvfb,
    ...(audio ? { audio } : {}),
    game,
    renderer,
    encoder
  };
}

function runtimeIdentity(env: RuntimeEnv): RuntimeIdentity {
  return {
    streamId: env.streamId,
    deploymentId: env.deploymentId,
    runtimeInstanceId: env.runtimeInstanceId
  };
}

function parseRuntimeGameSource(env: NodeJS.ProcessEnv): RuntimeGameSource {
  if (!env.GAME_SOURCE_KIND || env.GAME_SOURCE_KIND === "sample") {
    return {
      kind: "sample",
      sampleGameId: parseSampleGameId(env.GAME_SOURCE_SAMPLE_ID)
    };
  }

  if (env.GAME_SOURCE_KIND !== "github_archive") {
    throw new Error(`Unsupported GAME_SOURCE_KIND: ${env.GAME_SOURCE_KIND}`);
  }

  if (!env.GAME_SOURCE_ARCHIVE_URL) {
    throw new Error("GAME_SOURCE_ARCHIVE_URL is required for github_archive");
  }

  return {
    kind: "github_archive",
    archiveUrl: env.GAME_SOURCE_ARCHIVE_URL,
    ...(env.GAME_SOURCE_REPOSITORY
      ? { repositoryFullName: env.GAME_SOURCE_REPOSITORY }
      : {}),
    ...(env.GAME_SOURCE_REF ? { ref: env.GAME_SOURCE_REF } : {}),
    ...(env.GAME_SOURCE_COMMIT_SHA
      ? { commitSha: env.GAME_SOURCE_COMMIT_SHA }
      : {})
  };
}

function parseSampleGameId(value: string | undefined) {
  if (!value || value === "sample-game") {
    return "sample-game" as const;
  }

  throw new Error(`Unsupported GAME_SOURCE_SAMPLE_ID: ${value}`);
}

function parsePositiveInt(value: string, name: string) {
  const parsed = Number(value);

  if (!Number.isInteger(parsed) || parsed <= 0) {
    throw new Error(`${name} must be a positive integer`);
  }

  return parsed;
}

function parseVideoCodec(value: string): VideoCodec {
  if (value === "h264" || value === "hevc" || value === "av1") {
    return value;
  }

  throw new Error(`VIDEO_CODEC must be one of h264, hevc, av1`);
}

function parseAudioCodec(value: string): AudioCodec {
  if (value === "aac") {
    return value;
  }

  throw new Error("AUDIO_CODEC must be aac for YouTube RTMP/RTMPS ingest");
}

function parseAdaptiveBitrate(env: NodeJS.ProcessEnv): AdaptiveBitrateOptions {
  return {
    enabled: env.ADAPTIVE_BITRATE_ENABLED !== "false",
    minimumVideoBitrate: env.MIN_VIDEO_BITRATE ?? "1500k",
    stepDownRatio: parseRatio(
      env.ADAPTIVE_BITRATE_STEP_DOWN_RATIO ?? "0.75",
      "ADAPTIVE_BITRATE_STEP_DOWN_RATIO"
    ),
    congestionSpeedThreshold: parseRatio(
      env.CONGESTION_SPEED_THRESHOLD ?? "0.9",
      "CONGESTION_SPEED_THRESHOLD"
    ),
    congestionSampleCount: parsePositiveInt(
      env.CONGESTION_SAMPLE_COUNT ?? "3",
      "CONGESTION_SAMPLE_COUNT"
    )
  };
}

function parseRatio(value: string, name: string) {
  const parsed = Number(value);

  if (!Number.isFinite(parsed) || parsed <= 0 || parsed >= 1) {
    throw new Error(`${name} must be a number greater than 0 and less than 1`);
  }

  return parsed;
}

