import { spawn } from "node:child_process";
import { buildRuntimeChildEnv } from "./process-env.js";

import type { ChildProcess, SpawnOptions } from "node:child_process";
import type { LogForwarder } from "./log-forwarder.js";

export type ProcessLauncher = (
  command: string,
  args: readonly string[],
  options: SpawnOptions
) => ChildProcess;

export class XvfbController {
  private process: ChildProcess | undefined;

  constructor(
    private readonly options: {
      display: string;
      width: number;
      height: number;
      launcher?: ProcessLauncher;
      logs: LogForwarder;
    }
  ) {}

  async start() {
    const launcher = this.options.launcher ?? spawn;
    this.process = launcher(
      "Xvfb",
      [
        this.options.display,
        "-screen",
        "0",
        `${this.options.width}x${this.options.height}x24`,
        "-ac",
        "+extension",
        "GLX",
        "+render",
        "-noreset"
      ],
      { stdio: "pipe", env: buildRuntimeChildEnv() }
    );
    this.attachLogs();
    this.options.logs.emit("xvfb", "info", `Xvfb started on ${this.options.display}`);
  }

  async stop() {
    this.process?.kill("SIGTERM");
    this.process = undefined;
  }

  private attachLogs() {
    this.process?.stdout?.on("data", (data: Buffer | string) => {
      this.options.logs.emit("xvfb", "info", String(data).trim());
    });
    this.process?.stderr?.on("data", (data: Buffer | string) => {
      this.options.logs.emit("xvfb", "warn", String(data).trim());
    });
    this.process?.on("exit", (code, signal) => {
      this.options.logs.emit("xvfb", code === 0 ? "info" : "error", `Xvfb exited code=${code} signal=${signal}`);
    });
  }
}
